// data/duo_s1.js — Banque « Questions à deux » (App.DuoBank), semestre 1.
// Questions OUVERTES, à poser à voix haute : celui qui interroge a sous les yeux la question, la réponse attendue,
// les points à vérifier et des relances. Tout vient de TES notes Notion (B.1 : mêmes sources que les partiels blancs ;
// A.2 : exercice de la profession, secret professionnel, TD3, TD4, droits du patient ; E.1 : recherche documentaire).
//   - Une question dont la réponse est incomplète ou « à valider » dans tes notes porte un champ `chk` (avertissement affiché).
//   - D.1 est volontairement absent (demandé). A.1 : notes trop minces pour écrire des questions fiables.
//   - NE PAS réordonner ni supprimer : l'identifiant d'une question = id du set + son rang (la progression « à revoir »
//     en dépend). Pour en ajouter : à la FIN de la liste `items` du set.
// Champs : c = chapitre, q = question, a = réponse attendue, pts = points à vérifier (cocher mentalement),
//          rel = relances [question, réponse], chk = avertissement.
'use strict';
window.App = window.App || {};

App.DuoBank = (() => {
  const I = (c, q, a, pts, rel, chk) => ({ c, q, a, pts: pts || [], rel: rel || [], chk: chk || '' });

  const B1 = {
    id: 'B1', ue: 'B.1', name: 'Sciences biomédicales', ico: '🫀',
    blurb: 'Cœur, vaisseaux, respiration, douleur, homéostasie, pharmaco : les questions de tes CM et TD du S1.',
    exam: 'Partiel écrit (QRU / QRM), 1 h 30 — le 28/01/2027 d’après ton agenda.',
    note: 'Normes et seuils : ceux de TON cours (ex. gaz du sang). Si ton formateur donne d’autres valeurs, ce sont les siennes qui comptent.',
    chapters: {
      CM2: 'Biologie cellulaire', CM4: 'Homéostasie, pH, thermorégulation', CM5: 'Circulation', CM6: 'Douleur',
      CM14: 'Pathologies coronaires', CM15: 'AOMI et ischémie aiguë', CM16: 'Insuffisance cardiaque', CM17: 'TVP et embolie pulmonaire',
      CM18: 'Fibrillation atriale', CM19: 'Valvulopathies', CM21: 'Respiration et gaz du sang', CM22: 'Tabac et prévention respiratoire',
      CM23: 'Asthme, BPCO, SAHOS', TD3: 'Pharmacologie : principes'
    },
    items: [
      // ── CM2 ──
      I('CM2', `Où se déroule la glycolyse, et quel est son bilan ?`,
        `Dans le cytoplasme : 1 glucose donne 2 pyruvates et 2 ATP.`,
        [`Cytoplasme (pas la mitochondrie)`, `1 glucose → 2 pyruvates`, `2 ATP produits`],
        [[`Et où ont lieu la décarboxylation, le cycle de Krebs et la phosphorylation oxydative ?`, `Dans la mitochondrie. La phosphorylation oxydative produit la majeure partie de l’ATP et l’oxygène en est l’accepteur final.`]]),
      I('CM2', `Compare la mitose et la méiose.`,
        `Mitose : 2 cellules filles identiques à 2n chromosomes (stabilité génétique). Méiose : 4 cellules haploïdes à n chromosomes, avec brassage génétique.`,
        [`Mitose = 2 cellules identiques, 2n`, `Méiose = 4 cellules haploïdes, n`, `Méiose = brassage génétique`],
        [[`À quel moment a lieu le crossing-over ?`, `Lors de la méiose I (recombinaison). Le brassage vient aussi de la ségrégation au hasard des chromosomes.`]]),
      // ── CM4 ──
      I('CM4', `Quelle est la compensation d’une acidose métabolique ? Et celle d’une acidose respiratoire ?`,
        `Acidose métabolique : compensation respiratoire rapide (minutes), par hyperventilation qui fait baisser la PCO₂. Acidose respiratoire : compensation rénale lente (jours), avec production de HCO₃⁻.`,
        [`Métabolique → poumons (hyperventilation, ↓PCO₂), rapide`, `Respiratoire → reins (↑HCO₃⁻), lent`],
        [[`Comment se caractérise une acidose respiratoire non compensée ?`, `Hausse de la PCO₂ avec baisse du pH.`]]),
      I('CM4', `Cite des causes d’acidose métabolique.`,
        `L’acido-cétose, l’acidose lactique et la diarrhée (perte de bicarbonates).`,
        [`Principe : gain d’H⁺ ou perte de HCO₃⁻`, `Acido-cétose`, `Acidose lactique`, `Diarrhée`],
        [[`Les vomissements donnent quel trouble ? Et l’hypoventilation ?`, `Vomissements → alcalose métabolique ; hypoventilation → acidose respiratoire.`]]),
      I('CM4', `Comment est répartie l’eau dans l’organisme ?`,
        `2/3 intracellulaire et 1/3 extracellulaire. L’extracellulaire se divise en 1/4 vasculaire et 3/4 interstitiel.`,
        [`2/3 intracellulaire`, `1/3 extracellulaire`, `Dans l’extracellulaire : 1/4 vasculaire, 3/4 interstitiel`],
        [[`Où reste le NaCl 0,9 % après perfusion ?`, `Dans le secteur extracellulaire.`]]),
      I('CM4', `Quelle est la différence entre fièvre et hyperthermie ?`,
        `Fièvre : le point de consigne hypothalamique est relevé (pyrogènes, souvent une infection). Hyperthermie : la régulation est dépassée par une chaleur extérieure trop forte.`,
        [`Fièvre = point de consigne augmenté`, `Hyperthermie = régulation dépassée`]),
      I('CM4', `Quelles sont les réponses de l’organisme au froid ? Et à la chaleur ?`,
        `Au froid : vasoconstriction cutanée, frisson, métabolisme augmenté (lipolyse de la graisse brune). À la chaleur : vasodilatation et sudation.`,
        [`Froid : limiter les pertes (vasoconstriction) ET produire de la chaleur (frisson, graisse brune)`, `Chaud : vasodilatation, sudation`]),
      // ── CM5 ──
      I('CM5', `Donne la formule du débit cardiaque et ses valeurs de repos et d’effort.`,
        `Qc = VES × FC. Environ 5 L/min au repos, jusqu’à 20 L/min à l’effort.`,
        [`Qc = volume d’éjection systolique × fréquence cardiaque`, `≈ 5 L/min au repos`, `Jusqu’à 20 L/min à l’effort`],
        [[`Quels sont les déterminants du VES ?`, `La précharge (remplissage), la postcharge (résistance à l’éjection) et la contractilité.`],
         [`Autre écriture du débit dans ton cours ?`, `Qc = PA ÷ résistances (une division, pas une multiplication).`]]),
      I('CM5', `Qu’est-ce que la fraction d’éjection et quelle est sa valeur normale dans ton cours ?`,
        `FE = VES ÷ VTD, environ 60 %. Valeurs du cours : VTD ≈ 120 mL, VTS ≈ 50 mL, VES ≈ 70 mL.`,
        [`FE = VES ÷ VTD`, `≈ 60 %`]),
      I('CM5', `Décris le cycle cardiaque : que marquent B1 et B2 ?`,
        `B1 marque le début de la systole (fermeture des valves atrio-ventriculaires). B2 marque le début de la diastole (fermeture des valves ventriculo-artérielles).`,
        [`B1 = début de systole`, `B2 = début de diastole`, `Systole : le ventricule éjecte, son volume diminue`, `Diastole : il se remplit`]),
      I('CM5', `Au repos, comment se répartit le débit cardiaque entre les organes ?`,
        `Environ : splanchnique 30 %, reins 25 %, cerveau 15 %, myocarde 5 %.`,
        [`Splanchnique ≈ 30 %`, `Reins ≈ 25 %`, `Cerveau ≈ 15 %`, `Myocarde ≈ 5 %`],
        [[`Et à l’effort ?`, `Les muscles squelettiques peuvent recevoir jusqu’à 80 % du débit (Qc 20 L/min), au détriment des reins et de la circulation splanchnique.`]]),
      I('CM5', `Quelles sont les définitions de l’HTA et de l’hypotension dans ton cours ?`,
        `HTA : pression artérielle supérieure à 140/90 mmHg. Hypotension : inférieure à 90/60 mmHg.`,
        [`HTA > 140/90`, `Hypotension < 90/60`]),
      // ── CM6 ──
      I('CM6', `Donne la définition de la douleur (IASP) et la limite entre douleur aiguë et chronique.`,
        `Expérience sensorielle ET émotionnelle désagréable. Aiguë : moins de 3 mois ; chronique : plus de 3 mois.`,
        [`Sensorielle ET émotionnelle`, `Aiguë < 3 mois`, `Chronique > 3 mois`]),
      I('CM6', `Quelles fibres transmettent la « première douleur » et lesquelles la douleur tardive ?`,
        `Fibres A-delta : première douleur rapide, bien localisée (10-20 m/s). Fibres C : douleur diffuse et tardive, type brûlure (1-2 m/s).`,
        [`A-delta = rapide, localisée`, `C = lente, diffuse, brûlure`],
        [[`Et les fibres A-bêta ?`, `Tact et proprioception : elles ne transmettent pas la douleur.`]]),
      I('CM6', `Distingue douleur nociceptive, neuropathique et nociplastique.`,
        `Nociceptive : excès de stimulation périphérique, répond aux antalgiques classiques. Neuropathique : lésion du système nerveux (brûlures, décharges électriques, allodynie, hyperalgésie), traitement spécifique (gabapentine, antidépresseurs). Nociplastique : sans lésion identifiée (ex. fibromyalgie), dysfonction des systèmes de modulation.`,
        [`Nociceptive → antalgiques classiques`, `Neuropathique → lésion nerveuse, brûlures/décharges, traitement spécifique`, `Nociplastique → pas de lésion identifiée (fibromyalgie)`]),
      I('CM6', `Quels sont les paliers du traitement antalgique ?`,
        `Palier 1 (EN 1-3/10) : paracétamol, AINS. Palier 2 (EN 4-6/10) : codéine, tramadol. Palier 3 (EN ≥ 7/10) : opioïdes forts.`,
        [`P1 non opioïdes`, `P2 opioïdes faibles`, `P3 opioïdes forts ± co-analgésiques`, `Choix selon l’intensité (échelle numérique)`]),
      I('CM6', `Quel outil d’évaluation de la douleur selon l’âge de l’enfant ?`,
        `0-4 ans : hétéro-évaluation (EVENDOL ou FLACC). 4-6 ans : échelle des visages (FPS-R). 6-8 ans : EVA verticale ou visages. Dès 8 ans : EN ou EVA.`,
        [`0-4 ans → hétéro-évaluation`, `4-6 ans → visages`, `Dès 8 ans → EN / EVA`]),
      I('CM6', `Qu’est-ce qu’une douleur projetée (référée) ? Donne un exemple.`,
        `Une douleur ressentie dans une région différente de la lésion. Exemple : lésion hépatique ressentie à l’épaule droite (ou hanche → genou).`,
        [`Ressentie ailleurs que sur la lésion`, `Foie → épaule droite`]),
      // ── CM14 ──
      I('CM14', `Que veut dire « vascularisation terminale » pour les coronaires, et quel territoire irrigue l’IVA ?`,
        `Chaque partie du myocarde est nourrie par une seule artère : une obstruction aiguë ne peut pas être suppléée et entraîne la nécrose. L’IVA vascularise la partie antérieure, latérale et septale du myocarde.`,
        [`Pas de suppléance → nécrose`, `IVA : antérieur, latéral, septal`],
        [[`D’où naissent l’IVA et la circonflexe ? Et que vascularise la coronaire droite ?`, `Du tronc commun gauche. La coronaire droite vascularise la paroi inférieure.`]]),
      I('CM14', `Qu’est-ce que l’athérosclérose et quels sont ses facteurs de risque ?`,
        `Maladie inflammatoire de la paroi artérielle avec plaques d’athérome (cœur lipidique recouvert d’une chape fibreuse). Facteurs : âge, sexe masculin, HTA, diabète, tabac, hérédité, surpoids, sédentarité.`,
        [`Inflammatoire, plaques d’athérome`, `Cœur lipidique + chape fibreuse`, `Âge, sexe masculin, HTA, diabète, tabac, hérédité, surpoids, sédentarité`]),
      I('CM14', `Compare SCA ST+ et SCA ST−, et dis quel est le traitement du ST+.`,
        `ST+ : sus-décalage du ST, thrombus totalement occlusif, reperfusion en urgence absolue. ST− : sous-décalage du ST, thrombus non totalement occlusif, reperfusion rapide pour éviter l’évolution vers le ST+.`,
        [`ST+ = occlusion totale`, `ST− = thrombus non totalement occlusif`, `ST+ → reperfusion en urgence absolue`, `Rôle infirmier : douleur thoracique = alerte immédiate`]),
      I('CM14', `Comment distinguer un angor d’un infarctus devant une douleur thoracique ?`,
        `Angor : douleur rétro-sternale, constrictive, à l’effort, qui cède à l’arrêt de l’effort ; moins de 30 minutes et sensible aux nitrates. Infarctus : plus de 30 minutes, résistante aux nitrates, avec signes ECG concordants.`,
        [`Angor : effort, cède au repos, < 30 min, nitrates efficaces`, `Infarctus : > 30 min, résistant aux nitrates, ECG concordant`],
        [[`Que peut montrer l’ECG percritique dans l’angor ?`, `Sous-décalage du ST ou ondes T négatives ; il peut aussi être normal. La confirmation finale se fait par coronarographie.`]]),
      I('CM14', `Que signifie BASIC pour le traitement médicamenteux de la maladie coronaire ?`,
        `Bêtabloquant, Antiagrégants plaquettaires, Statine, IEC, Contrôle des facteurs de risque.`,
        [`B = bêtabloquant`, `A = antiagrégants`, `S = statine`, `I = IEC`, `C = contrôle des facteurs de risque`]),
      I('CM14', `Quelles sont les options de revascularisation coronaire ?`,
        `L’angioplastie avec pose de stent (indiquée en première intention dans la majorité des cas) ou le pontage aorto-coronarien (vaisseau sain implanté en aval de la sténose). L’examen clé est la coronarographie.`,
        [`Angioplastie + stent`, `Pontage aorto-coronarien`, `Coronarographie = examen clé`]),
      // ── CM15 ──
      I('CM15', `Quels sont les stades de l’AOMI ?`,
        `Stade 1 : asymptomatique. Stade 2 : claudication (douleur à la marche). Stade 3 : douleurs de décubitus. Stade 4 : troubles trophiques. Les stades 3 et 4 sont l’ischémie critique.`,
        [`1 asymptomatique`, `2 claudication`, `3 douleurs de décubitus`, `4 troubles trophiques`],
        [[`Comment se calcule l’IPS ?`, `Pression systolique de cheville ÷ pression systolique du bras, au doppler, patient allongé. Un IPS < 0,9 évoque une AOMI.`]],
        `Le seuil de 0,9 vient des compléments de tes notes : à valider avec ton cours.`),
      I('CM15', `Quels sont les signes d’une ischémie aiguë de membre et la conduite à tenir ?`,
        `Douleur, pâleur, froideur, abolition des pouls, veines vides et collabées, signes neurologiques. C’est une urgence chirurgicale : voies d’abord veineuses, sonde urinaire, antalgiques, héparinothérapie, revascularisation en urgence.`,
        [`Membre froid et pâle, pouls abolis, veines vides`, `Urgence chirurgicale : ne pas perdre de temps`, `Revascularisation en urgence`],
        [[`Quelles sont les causes ?`, `Embolie d’origine cardiaque, traumatisme, thrombose sur artère pathologique.`]]),
      I('CM15', `Quel est le traitement médical de fond de l’AOMI ?`,
        `Règles hygiéno-diététiques (arrêt du tabac, marche régulière), antiagrégant plaquettaire, statine, traitement du diabète et de l’HTA. La revascularisation est envisagée selon la gravité.`,
        [`Arrêt du tabac, marche`, `Antiagrégant + statine`, `Diabète et HTA traités`]),
      // ── CM16 ──
      I('CM16', `Donne les signes d’insuffisance cardiaque gauche et ceux d’insuffisance cardiaque droite.`,
        `Gauche : crépitants pulmonaires, choc de pointe dévié, galop (B3, B4), épanchements pleuraux (congestion pulmonaire + bas débit). Droite : œdèmes des membres inférieurs, turgescence jugulaire, reflux hépato-jugulaire, ascite (congestion systémique).`,
        [`Gauche = poumon (crépitants)`, `Droite = systémique (OMI, jugulaires, foie, ascite)`]),
      I('CM16', `Décris la classification NYHA.`,
        `I : aucune limitation. II : limitation modeste. III : réduction marquée (un effort modeste donne des symptômes). IV : symptômes au repos.`,
        [`I aucune limitation`, `II modeste`, `III marquée`, `IV au repos`]),
      I('CM16', `Quels traitements améliorent la survie dans l’insuffisance cardiaque systolique ? Et les diurétiques ?`,
        `IEC, bêtabloquants et anti-aldostérone (patients très symptomatiques, FEVG ≤ 35 %). Les diurétiques soignent les signes (congestion), pas la maladie, et sont toujours associés à un IEC ou un ARA II.`,
        [`IEC, bêtabloquants, anti-aldostérone → survie`, `Diurétiques → signes seulement`, `AINS à éviter`],
        [[`Qu’est-ce qu’on vérifie avant un IEC ?`, `La fonction rénale et l’ionogramme. Doses d’initiation faibles, augmentation après 2 à 4 semaines, pas d’augmentation si dégradation rénale ou hyperkaliémie. ARA II = alternative en cas d’intolérance.`]]),
      I('CM16', `Quels examens en première ligne devant une suspicion d’insuffisance cardiaque ? Et quels signes évoquent un OAP ?`,
        `BNP ou NT-proBNP en première ligne, puis échographie cardiaque (examen clé). OAP : urgence avec orthopnée intense, toux quinteuse, expectoration mousseuse rosée, angoisse, cyanose.`,
        [`BNP / NT-proBNP puis écho`, `OAP : expectoration mousseuse rosée, orthopnée`]),
      // ── CM17 ──
      I('CM17', `Que contient la triade de Virchow ? Quel est l’examen de référence de la TVP ?`,
        `Altération de la paroi veineuse, stase veineuse, hypercoagulabilité. Examen de référence de la TVP : écho-doppler veineux (veine incompressible).`,
        [`Paroi + stase + hypercoagulabilité`, `Écho-doppler veineux`],
        [[`Limites de l’écho-doppler ?`, `Opérateur-dépendant, gêné par des œdèmes importants. Avantages : non invasif, pas d’iode.`]]),
      I('CM17', `Que sont les D-dimères et à quoi servent-ils ?`,
        `Produits de dégradation spécifiques de la fibrine. Sensibles mais non spécifiques : un taux sous le seuil (500 ng/mL) exclut la MTEV, mais ils peuvent être élevés en cas d’infection, de cancer ou d’inflammation.`,
        [`Utiles surtout quand ils sont négatifs`, `Seuil 500 ng/mL`, `Peuvent être élevés dans infection, cancer, inflammation`]),
      I('CM17', `Qu’est-ce qui caractérise une embolie pulmonaire grave ?`,
        `Oblitération d’une artère pulmonaire proximale, insuffisance cardiaque droite aiguë, syncope ou malaise, signes de choc. Mortalité à 30 jours d’après ton cours : environ 12 % après une EP et 6 % après une TVP.`,
        [`Artère proximale`, `IC droite aiguë`, `Syncope / choc`],
        [[`Quel examen d’imagerie en cas d’allergie à l’iode ou d’insuffisance rénale ?`, `La scintigraphie, si l’angio-scanner est impossible. L’angio-scanner est très performant pour les EP proximales.`]]),
      // ── CM18 ──
      I('CM18', `Quel est l’aspect de la fibrillation atriale à l’ECG et quels sont ses risques ?`,
        `Tachycardie irrégulière à QRS fins, sans onde P (trémulation de la ligne iso-électrique). Risque n°1 : AVC par embolie d’un thrombus intra-cardiaque. Risque n°2 : insuffisance cardiaque.`,
        [`Irrégulière, QRS fins, pas d’onde P`, `AVC = risque n°1`, `Insuffisance cardiaque = risque n°2`, `Holter 24 h si symptômes intermittents`],
        [[`Cite des causes de FA.`, `Valvulopathies mitrales, myocardiopathie hypertrophique du sujet âgé hypertendu, hyperthyroïdie (les trois « +++ »). FA idiopathique = diagnostic d’exclusion.`]]),
      I('CM18', `Quels sont les trois principes du traitement de la FA ?`,
        `1) Anticoagulation (l’urgence : prévenir le risque thrombotique). 2) Ralentissement (bêtabloquants, digoxine). 3) Réduction (choc électrique ou cordarone), seulement après s’être assuré de l’absence de thrombus.`,
        [`Anticoagulation en premier`, `Ralentir`, `Réduire, après avoir exclu un thrombus`],
        [[`Quels traitements complémentaires ?`, `Ablation (isolement des veines pulmonaires, cryo-ablation ou radiofréquence, cathéter par la veine fémorale puis septum) ; occlusion de l’auricule gauche si l’anticoagulation est contre-indiquée ou trop risquée.`]]),
      // ── CM19 ──
      I('CM19', `Quelle est la valvulopathie la plus fréquente en Europe et quels sont ses trois symptômes ?`,
        `Le rétrécissement aortique calcifié (RAC). Symptômes : syncope, dyspnée, angor, d’abord à l’effort puis au repos.`,
        [`RAC, sujet âgé`, `Syncope, dyspnée, angor`, `Diagnostic : ETT (gradient, surface)`],
        [[`Quelles sont les causes de valvulopathies ?`, `Dégénérative (1ère cause en pays occidentaux), rhumatisme articulaire aigu, endocardite, congénitales.`]]),
      I('CM19', `Compare prothèse mécanique et bioprothèse. Qu’est-ce que le TAVI ?`,
        `Mécanique : durable mais AVK à vie avec surveillance de l’INR. Bioprothèse : durabilité limitée (10-15 ans), pas d’anticoagulation sans autre indication. TAVI : valve biologique posée par voie artérielle fémorale, sans anesthésie générale, pour patients âgés ou fragiles.`,
        [`Mécanique → AVK à vie, INR`, `Bioprothèse → 10-15 ans, pas d’AVK`, `TAVI → voie fémorale, sans AG`],
        [[`Que surveille-t-on chez un porteur de prothèse valvulaire ?`, `Fièvre inexpliquée (endocardite), saignement sous anticoagulant, déficit neurologique brutal (embolie), dyspnée nouvelle (dysfonction de la prothèse). Éducation, observance, suivi cardiologique annuel et dentaire.`]]),
      // ── CM21 ──
      I('CM21', `Quelles sont les normes des gaz du sang dans ton cours ?`,
        `PaO₂ 86 à 100 mmHg, PaCO₂ 38 à 42 mmHg, pH 7,38 à 7,42, SaO₂ 97 %.`,
        [`PaO₂ 86-100`, `PaCO₂ 38-42`, `pH 7,38-7,42`, `SaO₂ 97 %`],
        [[`Sur quel sang se font les gaz du sang ?`, `Sur du sang artériel. Les normes habituelles sont plus larges (PaCO₂ 35-45, pH 7,35-7,45) : retiens celles de ton cours.`]]),
      I('CM21', `Comment fonctionne la ventilation, et que change le niveau d’un obstacle des voies aériennes ?`,
        `L’inspiration est active (diaphragme), l’expiration calme est passive (élasticité du poumon, élastine). Obstacle en haut : dyspnée inspiratoire. Obstacle en bas : dyspnée expiratoire (ex. crise d’asthme).`,
        [`Inspiration active`, `Expiration passive`, `Haut → dyspnée inspiratoire`, `Bas → dyspnée expiratoire`],
        [[`Quel est le rôle du surfactant ?`, `Réduire la tension de surface alvéolaire et empêcher l’alvéole de s’affaisser. Insuffisant chez le prématuré → détresse respiratoire.`]]),
      I('CM21', `Comment l’oxygène est-il transporté ? Pourquoi le CO est-il dangereux ?`,
        `Environ 98 % lié à l’hémoglobine, 2 % dissous dans le plasma. Le CO se fixe sur le fer de l’hème à la place de l’O₂ (carboxyhémoglobine), d’où une anoxie cellulaire ; traitement : caisson hyperbare.`,
        [`98 % Hb / 2 % dissous`, `CO → carboxyhémoglobine → anoxie`],
        [[`Distingue hypoxémie, hypoxie, anoxie.`, `Hypoxémie : baisse de la quantité d’O₂ dans le sang. Hypoxie : baisse de l’apport d’O₂ aux cellules. Anoxie : baisse très importante de l’apport aux tissus.`]]),
      I('CM21', `Quels sont les mécanismes de protection des voies aériennes inférieures ? Qu’est-ce qu’un pneumothorax ?`,
        `Larynx (épiglotte et cordes vocales à la déglutition), escalator muco-ciliaire, réflexe de toux. Pneumothorax : air dans la cavité pleurale, la pression négative disparaît et le poumon se rétracte.`,
        [`Larynx, escalator muco-ciliaire, toux`, `Pneumothorax = air dans la plèvre, poumon rétracté`]),
      // ── CM22 ──
      I('CM22', `Quelles sont les 5 étapes de la consultation courte de tabacologie ?`,
        `Demander, conseiller, évaluer, accompagner, orienter (D.C.É.A.O.).`,
        [`Demander`, `Conseiller`, `Évaluer`, `Accompagner`, `Orienter`],
        [[`Quelles maladies sont liées au tabac ?`, `Cancers bronchiques et pulmonaires, BPCO, asthme de l’adulte, apnée du sommeil, tuberculose. La mucoviscidose est génétique, pas liée au tabac.`]]),
      I('CM22', `Que dit ton cours sur la vaccination (grippe, pneumocoque, zona, DTPCoq) ?`,
        `Grippe : chaque année. Pneumocoque : une seule fois dans la vie. Zona : 2 doses à partir de 65 ans. Rappel DTPCoq à 45 ans, puis tous les 10 ans à partir de 65 ans.`,
        [`Grippe annuelle`, `Pneumocoque une fois`, `Zona 2 doses dès 65 ans`, `DTPCoq 45 ans puis tous les 10 ans dès 65 ans`],
        [[`Qui peut prescrire la vaccination ?`, `Les infirmiers formés et déclarés à l’Ordre (décret du 8 août 2023). Le VRS est recommandé à partir de 75 ans.`]]),
      // ── CM23 ──
      I('CM23', `Comment prouve-t-on la réversibilité de l’obstruction dans l’asthme, et quel est son traitement de fond ?`,
        `Augmentation du VEMS sous bronchodilatateur de plus de 200 mL et plus de 12 %. Traitement de fond : corticoïdes inhalés (anti-inflammatoire), avec un bronchodilatateur d’action rapide à la demande.`,
        [`VEMS + 200 mL ET + 12 %`, `Corticoïdes inhalés = fond`, `Bon contrôle : ACT > 20`],
        [[`Dans la BPCO, l’obstruction est-elle réversible ?`, `Non.`]]),
      I('CM23', `Quels signes traduisent une exacerbation d’asthme grave ?`,
        `Phrases hachées en mots, FR > 30/min, FC > 120/min, SpO₂ < 90 %, DEP ≤ 50 % de la théorique (ou < 150 L/min).`,
        [`Parole difficile`, `FR > 30`, `FC > 120`, `SpO₂ < 90 %`, `DEP ≤ 50 %`]),
      I('CM23', `Décris la BPCO : cause, caractéristiques, prise en charge.`,
        `Obstruction bronchique non réversible et progressive ; le tabac est responsable de plus de 80 % des cas ; déficit en alpha-1 antitrypsine = seul facteur génétique identifié ; l’emphysème est la destruction des parois alvéolaires. Traitement : arrêt du tabac, bronchodilatateurs inhalés ± corticoïdes inhalés, vaccins, activité physique, O₂ si hypoxémie.`,
        [`Non réversible, progressive`, `Tabac > 80 %`, `Arrêt du tabac en premier`],
        [[`Que veut dire le stade 4 de l’échelle mMRC ?`, `Dyspnée au moindre effort de la vie courante.`]]),
      I('CM23', `Qu’est-ce qu’une exacerbation de BPCO, et quelles sont ses causes et sa prise en charge ?`,
        `Aggravation des symptômes respiratoires de plus de 24 heures ; pronostic vital engagé en cas d’acidose respiratoire décompensée (pH ≤ 7,35) ; cyanose = signe de faillite. Causes : infection, OAP, embolie pulmonaire, pneumothorax, iatrogénie (benzodiazépines, abus d’oxygène). Traitement : O₂ adapté, bronchodilatateurs nébulisés, VNI/intubation si besoin, corticoïdes, antibiotiques.`,
        [`> 24 h`, `Acidose respiratoire décompensée (pH ≤ 7,35) = gravité`, `Causes iatrogènes : benzodiazépines, excès d’O₂`]),
      I('CM23', `Qu’est-ce que le SAHOS et comment se classe sa gravité ?`,
        `Fermeture du pharynx à l’inspiration pendant le sommeil. IAH : < 5 normal ; 5-15 léger ; 15-30 modéré ; ≥ 30 sévère. Examen de référence : polysomnographie. L’alcool et les benzodiazépines l’aggravent ; la PPC doit être utilisée à toutes les périodes de sommeil (nuit et sieste).`,
        [`Fermeture du pharynx à l’inspiration`, `IAH ≥ 30 = sévère`, `Polysomnographie`, `PPC à chaque sommeil`]),
      I('CM23', `Que doit faire l’infirmier après une prise de corticoïdes inhalés ?`,
        `Faire se rincer la bouche (risque de mycose et de dysphonie). Passage systémique faible : pas de surveillance de la glycémie. Vérifier la technique d’inhalation : un traitement mal pris est inefficace.`,
        [`Rinçage de bouche`, `Technique d’inhalation vérifiée`]),
      // ── TD3 ──
      I('TD3', `Quelle est la règle des « 5B » avant d’administrer un médicament ?`,
        `Bon patient, bon médicament, bonne dose, bonne voie, bon moment.`,
        [`Identité`, `Médicament (nom, péremption)`, `Dose`, `Voie`, `Horaire`]),
      I('TD3', `Qu’est-ce que l’effet de premier passage hépatique ?`,
        `Une partie du médicament pris par voie orale est métabolisée par le foie avant d’atteindre la circulation générale : la biodisponibilité diminue. La voie sublinguale (ex. trinitrine) et la voie IV l’évitent.`,
        [`Voie orale → foie avant la circulation générale`, `↓ biodisponibilité`, `Sublinguale et IV le contournent`]),
      I('TD3', `Différence entre agoniste et antagoniste ? Et entre pharmacodynamie et pharmacocinétique ?`,
        `Agoniste : active le récepteur. Antagoniste : se fixe sans l’activer et bloque l’action de l’agoniste. Pharmacodynamie : mécanisme d’action. Pharmacocinétique : devenir du médicament dans l’organisme (ADME).`,
        [`Agoniste active, antagoniste bloque`, `PD = mécanisme`, `PK = devenir (ADME)`]),
      I('TD3', `Un patient a reçu par erreur le traitement d’un autre patient : que fais-tu ?`,
        `Évaluer l’état clinique, prévenir le médecin sans délai, informer le patient de l’erreur, puis tracer et déclarer l’événement indésirable. Culture juste : la déclaration ne doit pas être associée à une sanction.`,
        [`État clinique`, `Médecin prévenu sans délai`, `Patient informé`, `Traçabilité + déclaration`]),
      I('TD3', `À quoi servent le RCP, la notice et la monographie ? Quelles voies sont entérales ?`,
        `RCP : document technique et réglementaire pour les professionnels. Notice : version simplifiée pour le patient. Monographie : synthèse dans une base de données. Voies entérales : orale, sublinguale, rectale (par le tube digestif) ; l’IV, l’IM et la SC sont parentérales.`,
        [`RCP → professionnels`, `Notice → patient`, `Monographie → synthèse`, `Entérale = tube digestif`]),
      // ── Ajouts : compléments S1 (CM2 à CM23) ──
      I('CM2', `Donne le bilan global de la respiration cellulaire. Que deviennent les pyruvates en cas d’hypoxie ?`,
        `1 glucose + 6 O₂ → ATP + 6 H₂O + 6 CO₂. Le cycle de Krebs et la phosphorylation oxydative ont lieu dans la mitochondrie ; la phosphorylation oxydative produit la majeure partie de l’ATP et l’oxygène est l’accepteur final des électrons. En hypoxie, les pyruvates sont transformés en lactates.`,
        [`Glucose + O₂ → ATP + H₂O + CO₂`, `Mitochondrie`, `O₂ = accepteur final des électrons`, `Hypoxie → lactates`]),
      I('CM4', `Quel trouble acido-basique provoquent les vomissements ? La diarrhée ? Une hypoventilation ?`,
        `Vomissements : alcalose métabolique. Diarrhée : perte de bicarbonates, donc acidose métabolique. Hypoventilation : accumulation de CO₂, donc acidose respiratoire.`,
        [`Vomissements → alcalose métabolique`, `Diarrhée → acidose métabolique (perte de HCO₃⁻)`, `Hypoventilation → acidose respiratoire (↑ PCO₂)`],
        [[`Qu’est-ce qu’une acidose métabolique en termes d’ions ?`, `Un gain d’H⁺ ou une perte d’HCO₃⁻.`]]),
      I('CM5', `De quoi dépend le volume d’éjection systolique ? Comment la fréquence cardiaque est-elle régulée ?`,
        `Le VES dépend de la précharge (remplissage), de la postcharge (résistance à l’éjection) et de la contractilité. La FC est augmentée par le système sympathique et diminuée par le parasympathique. Qc = FC × VES.`,
        [`Précharge`, `Postcharge`, `Contractilité`, `Sympathique ↑ FC, parasympathique ↓ FC`]),
      I('CM14', `Décris la douleur de l’angor (maladie coronaire chronique) et ce que montre l’ECG. Quel examen confirme le diagnostic ?`,
        `Douleur rétro-sternale, constrictive, déclenchée par l’effort et qui cesse à l’arrêt de l’effort (l’ischémie apparaît à l’effort et disparaît au repos). L’ECG percritique peut montrer un sous-décalage du ST ou des ondes T négatives, mais peut aussi être normal. La confirmation se fait par la coronarographie.`,
        [`Rétro-sternale, constrictive, à l’effort`, `Cesse à l’arrêt de l’effort`, `ECG : sous-décalage ST ou T négatives, ou normal`, `Coronarographie`]),
      I('CM15', `Comment calcule-t-on l’IPS et que suspecte-t-on quand il est bas ?`,
        `IPS = pression systolique de cheville ÷ pression systolique du bras, mesurée au doppler, patient allongé. Un IPS inférieur à 0,9 évoque une AOMI.`,
        [`PAS cheville ÷ PAS bras`, `Doppler, patient allongé`, `< 0,9 évoque une AOMI`], [],
        `Le seuil de 0,9 vient des compléments de tes notes : à valider avec ton cours.`),
      I('CM15', `Qu’est-ce qu’une ischémie aiguë de membre inférieur et quelles sont ses causes ?`,
        `Une obstruction artérielle brutale : c’est la première cause d’intervention en urgence en chirurgie vasculaire. Le pronostic du membre et le pronostic vital sont engagés. Causes : embolie d’origine cardiaque, traumatisme, thrombose sur artère pathologique.`,
        [`Obstruction artérielle brutale`, `Urgence chirurgicale`, `Embolie cardiaque, traumatisme, thrombose`]),
      I('CM16', `De quelles façons peut-on classer une insuffisance cardiaque ?`,
        `Selon la fonction (systolique, avec FE altérée, ou diastolique, avec FE préservée), l’évolution (chronique ou aiguë), la localisation (gauche, droite ou globale) et la cause. Les formes aiguës graves sont l’OAP et le choc cardiogénique.`,
        [`Systolique ou diastolique`, `Chronique ou aiguë`, `Gauche, droite ou globale`, `Formes aiguës graves : OAP, choc cardiogénique`]),
      I('CM16', `Les IEC dans l’insuffisance cardiaque : indication, bénéfice, précautions, alternative ?`,
        `Ils sont indiqués chez tous les patients avec une FE < 40 % et augmentent la survie. On vérifie la fonction rénale et l’ionogramme avant la mise en route, on débute à faible dose et on augmente après 2 à 4 semaines, sans augmenter en cas de dégradation rénale ou d’hyperkaliémie. Les ARA II sont l’alternative en cas d’intolérance.`,
        [`FE < 40 %`, `↑ survie`, `Fonction rénale + ionogramme avant`, `Doses faibles, puis augmentation à 2-4 semaines`, `Intolérance → ARA II`],
        [[`Quel est l’effet indésirable typique des IEC ?`, `La toux sèche (les ARA II n’en donnent pas) ; aussi angio-œdème et hyperkaliémie.`]]),
      I('CM17', `Cite des facteurs de risque majeurs transitoires de maladie thrombo-embolique. Qu’est-ce qui est un facteur mineur ?`,
        `Majeurs transitoires : chirurgie avec anesthésie générale dans les 3 derniers mois, fracture d’un membre inférieur dans les 3 derniers mois, contraception œstro-progestative, immobilisation de plus de 3 jours pour motif médical aigu. Un voyage de plus de 6 heures est un facteur mineur transitoire. Cancer actif et thrombophilie majeure sont des facteurs majeurs persistants.`,
        [`Chirurgie AG ou fracture < 3 mois`, `Contraception œstro-progestative`, `Immobilisation > 3 jours`, `Voyage > 6 h = mineur`, `Cancer actif = majeur persistant`]),
      I('CM17', `Quels examens confirment une embolie pulmonaire ? Quelle est la gravité de la maladie thrombo-embolique ?`,
        `L’angio-scanner est très performant pour les embolies proximales ; la scintigraphie s’utilise s’il est impossible (allergie à l’iode, insuffisance rénale). La gravité tient à l’EP : mortalité à 30 jours d’environ 12 % après une EP et 6 % après une TVP. Près de 80 % des patients avec une EP ont une TVP, souvent asymptomatique.`,
        [`Angio-scanner en première intention`, `Scintigraphie si allergie à l’iode ou insuffisance rénale`, `Mortalité à 30 j : EP 12 %, TVP 6 %`, `80 % des EP ont une TVP`]),
      I('CM18', `Cite des causes de fibrillation atriale. Quel examen aide si les symptômes sont intermittents ?`,
        `Les trois causes « +++ » : valvulopathies mitrales, myocardiopathie hypertrophique du sujet âgé hypertendu, hyperthyroïdie ; aussi hypokaliémie et fièvre. Une FA sans cause retrouvée est dite idiopathique (diagnostic d’exclusion). Le Holter ECG (24 h) repère une FA intermittente.`,
        [`Valvulopathies mitrales`, `Myocardiopathie hypertrophique`, `Hyperthyroïdie`, `Holter ECG 24 h`]),
      I('CM18', `En quoi consistent l’ablation et l’occlusion de l’auricule dans la FA ?`,
        `Ablation (cryo-ablation ou radiofréquence) : on isole la zone des veines pulmonaires ; le cathéter est introduit par une veine fémorale puis passe dans l’oreillette gauche à travers le septum. L’occlusion de l’auricule gauche (la poche où se forment préférentiellement les thrombus) est envisagée si l’anticoagulation est contre-indiquée ou trop risquée.`,
        [`Isole les veines pulmonaires`, `Voie veineuse fémorale, traversée du septum`, `Auricule gauche = siège des thrombus`, `Si anticoagulation impossible ou trop risquée`]),
      I('CM19', `Quelles sont les causes des valvulopathies ? Que surveille-t-on chez un patient porteur d’une prothèse valvulaire ?`,
        `Causes : dégénérative (1ère cause dans les pays occidentaux), rhumatisme articulaire aigu (infections streptococciques répétées dans l’enfance), endocardite, causes congénitales. Prothèse : quatre risques — dysfonction ou dégénérescence (dyspnée nouvelle), hémorragie (saignement inhabituel sous anticoagulant), thrombo-embolie (déficit neurologique brutal), infection (fièvre inexpliquée : endocardite).`,
        [`Dégénérative, RAA, endocardite, congénitale`, `Dysfonction → dyspnée nouvelle`, `Hémorragie`, `Embolie → déficit neurologique`, `Endocardite → fièvre inexpliquée`]),
      I('CM21', `À quoi sert le surfactant ? Quelle différence entre hypoxémie, hypoxie et anoxie ?`,
        `Le surfactant réduit la tension de surface alvéolaire et empêche l’alvéole de s’affaisser (insuffisant chez le prématuré : détresse respiratoire). Hypoxémie : baisse de l’O₂ dans le sang. Hypoxie : baisse de l’apport d’O₂ aux cellules. Anoxie : baisse très importante de l’apport d’O₂ aux tissus.`,
        [`Surfactant : tension de surface ↓, alvéole ouverte`, `Hypoxémie = dans le sang`, `Hypoxie = aux cellules`, `Anoxie = très importante`]),
      I('CM23', `Que mesure l’échelle mMRC et à quoi correspond son stade 4 ?`,
        `mMRC : échelle de dyspnée. Stade 0 : efforts soutenus ; 1 : marche rapide ou en pente ; 2 : terrain plat en suivant quelqu’un ; 3 : arrêt après quelques minutes de marche ; 4 : dyspnée au moindre effort de la vie courante.`,
        [`Échelle de dyspnée`, `0 = efforts soutenus`, `3 = arrêt après quelques minutes`, `4 = moindre effort de la vie courante`]),
      I('CM6', `Comment se manifeste une douleur neuropathique et comment la traite-t-on ?`,
        `Elle est liée à une lésion du système nerveux : brûlures ou décharges électriques, fourmillements, parfois allodynie ou hyperalgésie. Elle demande un traitement spécifique (gabapentine, antidépresseurs), alors que la douleur nociceptive répond aux antalgiques classiques.`,
        [`Lésion du système nerveux`, `Brûlure, décharge électrique`, `Allodynie, hyperalgésie`, `Gabapentine, antidépresseurs`])
    ]
  };

  const A2 = {
    id: 'A2', ue: 'A.2', name: 'Législation, éthique, déontologie', ico: '⚖️',
    blurb: 'Exercice de la profession, secret professionnel, consentement, droits du patient, réserve et confraternité.',
    exam: 'Partiel écrit 1 h 30 (QCM / QCU / QROC), portant sur une situation clinique.',
    note: 'Textes cités (articles, arrêté du 26/06/2026…) : tels qu’écrits dans tes notes. Les points marqués « à valider » le sont aussi dans tes notes : vérifie-les avec ton formateur.',
    chapters: {
      EX: 'Exercice de la profession', SP: 'Secret professionnel', TD3: 'TD3 : consentement, information, personne de confiance',
      TD4: 'TD4 : réserve, discrétion, dossier', DR: 'Droits du patient, démocratie en santé',
      RS: 'Refus de soin, mineur, contrainte', ET: 'Éthique et bioéthique', VU: 'Vulnérabilité, fragilité, bientraitance'
    },
    items: [
      // ── Exercice de la profession ──
      I('EX', `Quels sont les trois cadres d’exercice de l’infirmier ?`,
        `Le rôle propre (R.4311-3), la collaboration (R.4311-5) et le rôle sur prescription médicale (R.4311-6).`,
        [`Rôle propre`, `Collaboration`, `Rôle sur prescription`]),
      I('EX', `Définis le rôle propre de l’infirmier.`,
        `Les actes que l’infirmier décide et réalise de sa propre initiative, dans le cadre de ses compétences (R.4311-3). Il prend en charge directement les patients et initie, accomplit et évalue les soins de la liste fixée par arrêté (R.4311-4), avec autonomie de jugement (R.4312-33).`,
        [`De sa propre initiative`, `Initier, accomplir, évaluer`, `Liste fixée par arrêté`, `Consultation infirmière reconnue en autonomie (nouveauté 2025-2026)`]),
      I('EX', `Qu’est-ce que la collaboration ? Qui est responsable ?`,
        `Des actes du rôle propre confiés par l’IDE, sous sa responsabilité, à un aide-soignant, auxiliaire de puériculture ou AES qu’il encadre (R.4311-5). Mot-clé : « travailler avec ». L’IDE engage sa propre responsabilité et s’assure de la compétence de la personne encadrée.`,
        [`AS / AP / AES diplômés`, `Actes du rôle propre confiés`, `L’IDE reste responsable`, `Il vérifie la compétence`],
        [[`Exemples d’actes délégués d’après tes notes ?`, `Toilette, alimentation, hydratation, prévention des thromboses ; glycémie capillaire et aspiration endotrachéale (trachéotomie cicatrisée) pour AS/AP ; surveillance d’une personne sous dialyse ou en chambre d’isolement.`]]),
      I('EX', `Qu’est-ce que le rôle sur prescription médicale ? Qui peut prescrire ?`,
        `Des actes réalisés en application d’une prescription médicale ou d’un protocole écrit (R.4311-6). Prescripteurs : médecin, sage-femme ou infirmier en pratique avancée (IPA). Le protocole est écrit, qualitatif et quantitatif, préalablement établi, daté et signé par un médecin.`,
        [`Prescription OU protocole écrit`, `Médecin, sage-femme, IPA`, `Exemples : injections, perfusions, prélèvements sanguins, sondes, médicaments`]),
      I('EX', `Quels sont les critères d’une prescription médicale ?`,
        `Elle doit être écrite (avant l’acte, sauf urgence), nominative, qualitative, quantitative, datée et signée.`,
        [`Écrite (sauf urgence)`, `Nominative : identifie le patient`, `Qualitative : produit/acte, posologie, lisible`, `Quantitative : dosage, durée, intervalle`, `Datée et signée`]),
      I('EX', `Que fait l’IDE en cas de doute sur une prescription ?`,
        `Il vérifie la prescription et alerte le prescripteur si nécessaire (devoir de vérification, R.4312-42).`,
        [`Vérifier`, `Alerter le prescripteur`, `R.4312-42`]),
      I('EX', `Que peut faire l’infirmier en situation d’urgence ?`,
        `En l’absence de médecin : protocoles de soins d’urgence écrits, datés et signés par le médecin responsable. Actes conservatoires en attendant le médecin, avec compte rendu écrit. En dehors de tout protocole : il décide des gestes à pratiquer et oriente la personne vers la structure la plus appropriée.`,
        [`Protocoles d’urgence écrits, datés, signés`, `Actes conservatoires + compte rendu écrit`, `Hors protocole : décide des gestes et oriente`]),
      I('EX', `Qu’a changé le texte de 2026 pour les infirmiers ?`,
        `Selon tes notes (arrêté du 26/06/2026) : autonomie vaccinale élargie (personnes de 11 ans et plus) et prescription infirmière élargie (vaccins, produits de santé, dispositifs médicaux, examens complémentaires ciblés).`,
        [`Vaccination en autonomie, 11 ans et plus`, `Prescription élargie`],
        [], `Textes récents : à confirmer avec le cours oral et l’arrêté.`),
      I('EX', `Pose d’une sonde vésicale prescrite par le médecin : quel rôle ? Et la vidange d’un dispositif de recueil ?`,
        `La pose de sonde vésicale relève du rôle sur prescription (avec les 5 critères de la prescription). La vidange du dispositif de recueil et le repérage d’anomalies liées aux cathéters, sondes et drains relèvent du rôle propre.`,
        [`Pose de sonde → prescription`, `Vidange / repérage d’anomalies → rôle propre`]),
      I('EX', `Vaccination antigrippale en EHPAD sans prescription : quel rôle ?`,
        `Le rôle propre : depuis le décret n°2022-610, l’IDE peut vacciner sans prescription médicale préalable. L’arrêté du 26/06/2026 confirme et élargit cette autonomie (11 ans et plus).`,
        [`Rôle propre`, `Décret n°2022-610`, `Sans prescription préalable`]),
      I('EX', `Une aide-soignante réalise une glycémie capillaire à la demande de l’IDE : quel rôle ? Qui est responsable ?`,
        `La collaboration : l’acte est délégué à l’AS (art. 2 de l’arrêté du 26/06/2026), sous la responsabilité de l’IDE, qui s’assure de sa compétence et vérifie les conditions de réalisation.`,
        [`Collaboration`, `L’IDE reste responsable`, `Compétence vérifiée`]),
      I('EX', `Arrêt cardio-respiratoire : que peut faire l’infirmier ?`,
        `Dégager les voies aériennes supérieures et initier le massage cardiaque. L’injection d’adrénaline suppose un protocole ou une prescription.`,
        [`Dégager les VAS`, `Massage cardiaque`, `Adrénaline : protocole ou prescription`],
        [], `Réponse proposée dans tes notes avec la mention « à vérifier ».`),
      // ── Secret professionnel ──
      I('SP', `À qui appartient le secret médical ? Le patient donne son accord oral pour qu’on parle de lui : est-ce suffisant ?`,
        `Le secret médical appartient au patient. Non : un accord oral du moment n’autorise pas à divulguer librement sa vie ou sa prise en charge ; le cadre légal du secret reste la référence.`,
        [`Appartient au patient`, `Accord oral ≠ autorisation de divulguer`]),
      I('SP', `Que couvre le secret professionnel ?`,
        `Les faits confiés par le patient ou appris de son entourage (même sans préciser que c’est secret), les constatations faites pendant les soins, les faits liés à la maladie et au traitement, tous les documents rédigés à l’occasion d’un acte médical, et les documents permettant d’identifier le patient ou de révéler sa présence dans un établissement.`,
        [`Confidences, même non déclarées secrètes`, `Constatations pendant les soins`, `État, affection, traitement`, `Documents`, `Présence dans l’établissement`]),
      I('SP', `Que change la loi du 4 mars 2002 (loi Kouchner) ?`,
        `Elle place le patient au cœur du système de santé : le secret n’est officiellement plus opposable à l’usager. Elle réaffirme ses droits (information, consentement, accès à son dossier…) et les droits liés à la santé.`,
        [`Patient au cœur du système`, `Information, consentement, accès au dossier`]),
      I('SP', `D’où vient le secret professionnel ? Quelle sanction en cas de violation ?`,
        `Serment d’Hippocrate ; inscrit pour la première fois dans le Code pénal de 1810. Violation : 1 an d’emprisonnement et 15 000 € d’amende (art. 226-13 du Code pénal).`,
        [`Hippocrate, Code pénal 1810`, `1 an + 15 000 €`, `226-13 CP`]),
      I('SP', `Combien de dérogations légales au secret professionnel existe-t-il ? Cite des « cas de conscience ».`,
        `36 dérogations légales, mais encadrées. Cas de conscience : le soignant et la justice, le constat de maltraitance sur mineur, les violences conjugales, les menaces envers un tiers, les maladies transmissibles (ex. VIH).`,
        [`36 dérogations, encadrées`, `Justice, maltraitance, violences conjugales, menaces, maladies transmissibles`, `Pas de déclaration obligatoire au conjoint (VIH)`],
        [], `Le détail des 36 dérogations n’est pas dans tes notes (captures non récupérées) et plusieurs sous-parties sont « à compléter ».`),
      I('SP', `Comment se partagent les informations dans une équipe de soins et hors équipe ?`,
        `Au sein d’une même équipe de soins : partage facilité, présumé accepté par le patient sauf opposition. Entre professionnels extérieurs à l’équipe : accord exprès du patient. Principe : ne partager que le nécessaire et le pertinent avec les professionnels directement concernés (L.1110-4).`,
        [`Équipe de soins : présumé accepté sauf opposition`, `Hors équipe : accord exprès`, `Strictement nécessaire`],
        [[`Quelle question te poser avant de transmettre une information à un collègue ?`, `« Est-ce que mon collègue a vraiment besoin de cette information pour une prise en charge correcte ? »`]]),
      I('SP', `Distingue secret professionnel, confidentialité, discrétion professionnelle, obligation de réserve et bonne confraternité.`,
        `Secret : interdiction de révéler une information sur le patient (obligation pénale). Confidentialité : devoir de protéger l’information (dossier, écrans, conversations). Discrétion : ne pas divulguer ce qu’on apprend du fonctionnement du service, même non secret. Réserve : s’exprimer avec mesure, pas de dénigrement public. Confraternité : respect et entraide, un différend se règle par la conciliation.`,
        [`Secret = patient, pénal`, `Confidentialité = protéger l’information`, `Discrétion = service, institution`, `Réserve = pas de dénigrement public`, `Confraternité = respect, conciliation`]),
      I('SP', `Qui annonce un résultat de sérologie VIH au patient ? Le VIH est-il une dérogation au secret ?`,
        `Le médecin. L’IDE ou l’ESI relaie l’inquiétude du patient à l’équipe. Non : le VIH ne fait l’objet d’aucune dérogation légale spécifique au secret.`,
        [`Annonce = médecin`, `Relayer l’inquiétude, tracer`, `Aucune dérogation pour le VIH`]),
      I('SP', `Un patient séropositif ne veut peut-être pas le dire à sa femme : que fais-tu ?`,
        `Dilemme éthique (autonomie et secret contre protection d’un tiers). On respecte le secret, sans laisser le patient seul : on l’écoute, on l’encourage à informer lui-même sa partenaire, on relaie au médecin et on trace. L’ESI ne décide jamais seule : elle alerte le médecin et le cadre. Révéler à l’épouse = violation du secret (226-13 CP).`,
        [`Respecter le secret`, `Encourager le patient à informer lui-même`, `Alerter médecin et cadre`, `Tracer`],
        [], `Le débat sur la non-assistance à personne en péril est signalé « débattu » dans tes notes.`),
      I('SP', `Un groupe d’étudiants sur Instagram est-il une équipe de soins ? L’étudiant est-il concerné par le secret ?`,
        `Non, il n’entre dans aucune exception au secret. Oui, l’étudiant est concerné : le code de déontologie s’applique aux ESI (R.4312-1) et l’art. 226-13 vise aussi une mission temporaire, donc un stage.`,
        [`Groupe d’étudiants ≠ équipe de soins`, `R.4312-1`, `Mission temporaire = stage`]),
      I('SP', `Une infirmière raconte à ses parents, au déjeuner, l’hospitalisation d’un patient : qu’en dis-tu ?`,
        `Elle viole le secret professionnel (L.1110-4 I, R.4312-5) et manque à son devoir de confidentialité : ses parents ne font pas partie de l’équipe de soins, le patient n’a pas consenti, aucune dérogation ne s’applique. Peu importe le repas de famille ou le jour de repos.`,
        [`Parents ≠ équipe de soins`, `Pas de consentement`, `Pas de dérogation`]),
      // ── TD3 ──
      I('TD3', `Qu’est-ce que le consentement et à quel article se rapporte-t-il ?`,
        `L’accord libre et éclairé du patient, recueilli avant tout acte ou traitement, retirable à tout moment : L.1111-4 CSP, décliné par R.4312-14 pour l’infirmier. « Toute personne prend, avec le professionnel de santé […] les décisions concernant sa santé. Aucun acte médical ni aucun traitement ne peut être pratiqué sans le consentement libre et éclairé de la personne. »`,
        [`Libre = sans pression`, `Éclairé = après explication`, `Préalable`, `Révocable à tout moment`, `L.1111-4 et R.4312-14`]),
      I('TD3', `En quoi consiste le devoir d’information ? Que peut dire l’infirmier ?`,
        `Tout patient a le droit d’être informé sur son état de santé (L.1111-2) ; le soignant a le devoir de délivrer, dans le cadre de ses compétences, une information loyale, claire et appropriée, préalable au consentement (R.4312-13). L’IDE informe sur les soins de sa compétence, pas sur les informations médicales (ex. résultats).`,
        [`Droit du patient / devoir du soignant`, `Loyale, claire, appropriée`, `Dans le cadre de ses compétences`]),
      I('TD3', `Dans quelles circonstances des professionnels peuvent-ils échanger des informations sur un patient ?`,
        `Le secret est la règle, l’échange est une exception strictement encadrée : seulement entre professionnels qui participent à la prise en charge, pour des informations strictement nécessaires à la coordination, à la continuité des soins, à la prévention ou au suivi médico-social, avec information du patient et respect de son droit d’opposition.`,
        [`Participent à la prise en charge`, `Strictement nécessaire`, `Patient informé`, `Droit d’opposition`]),
      I('TD3', `Qu’est-ce que la personne de confiance ?`,
        `Toute personne majeure peut en désigner une (parent, proche ou médecin traitant), par écrit, cosigné, révisable et révocable à tout moment ; proposée systématiquement lors d’une hospitalisation. Elle est consultée si le patient est hors d’état d’exprimer sa volonté et son témoignage prévaut ; elle témoigne de la volonté du patient, elle ne décide pas à sa place (L.1111-6).`,
        [`Majeure, désignée par écrit`, `Proposée à l’hospitalisation`, `Témoigne, ne décide pas`, `Peut accompagner aux entretiens`]),
      I('TD3', `Que sont les directives anticipées ?`,
        `Instructions écrites d’une personne majeure pour le cas où elle serait hors d’état d’exprimer sa volonté (fin de vie : poursuite, limitation, arrêt ou refus de traitement). Loi du 22 avril 2005, modifiée le 2 février 2016 (L.1111-11). Révisables et révocables à tout moment. Elles s’imposent au médecin sauf urgence vitale ou directives manifestement inappropriées (décision après procédure collégiale).`,
        [`Majeur, écrit, révocable`, `Loi 2005 modifiée 2016`, `S’imposent au médecin, avec 2 exceptions`, `Registre national`],
        [[`Combien de modèles ?`, `Deux : modèle A (maladie grave ou fin de vie) et modèle B (bonne santé) — arrêté du 3 août 2016.`]]),
      // ── TD4 ──
      I('TD4', `Quelle méthode pour répondre à une question de droit ?`,
        `4 temps : 1) Faits (que s’est-il passé, qui est concerné ?) ; 2) Règle (quelle notion, quel article ?) ; 3) Application (en quoi les faits correspondent à la règle ?) ; 4) Conséquence (quelle responsabilité pénale, civile, disciplinaire, et que faire concrètement ?).`,
        [`Faits`, `Règle`, `Application`, `Conséquence`]),
      I('TD4', `Comment un patient accède-t-il à son dossier médical ? Quels délais ?`,
        `C’est un droit (loi du 4 mars 2002, L.1111-7). Demande écrite à la direction de l’établissement, avec pièce d’identité ; consultation sur place gratuite ou copie (frais à sa charge). Délais : 48 h de réflexion minimum, puis 8 jours maximum (informations de moins de 5 ans) ou 2 mois (plus de 5 ans). Dossier conservé 20 ans. L’ESI oriente le patient, ne remet jamais le dossier.`,
        [`Demande écrite + identité`, `48 h minimum`, `8 jours (< 5 ans) / 2 mois (> 5 ans)`, `Conservé 20 ans`],
        [[`En cas de refus ou de silence ?`, `Relancer par écrit, saisir la commission des usagers, puis la CADA (hôpital public) dans les 2 mois, ou la CNIL.`]]),
      I('TD4', `Une étudiante publie un TikTok en tenue, dans le poste de soins : « #service de merde », insulte sa tutrice. Qu’en dis-tu ?`,
        `Elle manque à l’obligation de réserve, à la bonne confraternité et à l’honneur de la profession (R.4312-4, R.4312-9, R.4312-25) : dénigrement public d’un service identifiable, sur un compte à 1500 abonnés (circonstance aggravante). Elle aurait dû en parler directement à la tutrice, au cadre ou au formateur. Suites possibles : section disciplinaire de l’IFSI.`,
        [`Réserve, confraternité, honneur de la profession`, `Diffusion publique = aggravant`, `Bons canaux : tutrice, cadre, formateur`]),
      I('TD4', `Des étudiants s’écrivent sur Instagram : photos de résidents, critique d’une IDE, jugement sur un médecin nommé, un acteur célèbre cité. Qu’est-ce qui est en cause pour chacun ?`,
        `Photos de résidents : confidentialité, droit à l’image, secret. Critique de l’équipe avec lieu nommé : discrétion, confraternité, réserve. Jugement sur un médecin nommé : réserve, confraternité, atteinte à la réputation. Acteur célèbre venu voir sa mère : secret professionnel (la notoriété ne change rien).`,
        [`Photos → confidentialité / droit à l’image`, `Critique + lieu nommé → discrétion / confraternité`, `Médecin nommé → réserve`, `Personne célèbre → secret`],
        [[`Quels sont les bons réflexes ?`, `Critiquer son stage par les bons canaux (tuteur, cadre, formateur, évaluation de stage) ; ne jamais citer patient, lieu ou soignant ni prendre de photo sans autorisation ; analyse de pratique à l’IFSI, situation anonymisée.`]]),
      // ── Droits du patient / démocratie en santé ──
      I('DR', `Définis la démocratie en santé.`,
        `Une démarche associant l’ensemble des acteurs du système de santé dans l’élaboration et la mise en œuvre de la politique de santé, dans un esprit de dialogue et de concertation. Renforcée par la loi du 26 janvier 2016.`,
        [`Tous les acteurs associés`, `Dialogue et concertation`, `Loi du 26 janvier 2016`],
        [[`Qu’ont été les États généraux de la santé ?`, `1998-1999, plus de 1000 réunions dans 180 villes, environ 200 000 participants : donner la parole aux usagers et aller vers une démocratie sanitaire.`]]),
      I('DR', `Cite les 7 principes de la démocratie sanitaire (niveau individuel).`,
        `1) Droit fondamental à la protection de la santé (L.1110-1). 2) Respect de la dignité (L.1110-2, accès aux soins palliatifs). 3) Interdiction de la discrimination (L.1110-3). 4) Respect de la vie privée et du secret (L.1110-4). 5) Information des usagers (L.1111-2 à 9). 6) Expression de la volonté (L.1111-4). 7) Accès au dossier médical (L.1111-7).`,
        [`Protection de la santé`, `Dignité`, `Non-discrimination`, `Vie privée et secret`, `Information`, `Volonté / consentement`, `Accès au dossier`]),
      I('DR', `Que sont l’arrêt Mercier (1936) et l’arrêt Teyssier (1942) ?`,
        `Mercier (Cass. 20 mai 1936) : consacre un contrat entre médecin et patient, obligation de moyens (soins consciencieux, attentifs, conformes aux données de la science), pas de guérir. Teyssier (Cass. 28 janvier 1942) : le chirurgien doit obtenir le consentement du malade avant toute opération ; le manquement est une faute personnelle.`,
        [`Mercier → contrat, obligation de moyens`, `Teyssier → consentement avant opération`]),
      I('DR', `Qu’est-ce que le dispositif CRCI-ONIAM ?`,
        `Procédure amiable pour les dommages liés aux soins : les CRCI (commissions régionales de conciliation et d’indemnisation) sont des instances extra-judiciaires de conciliation ; l’ONIAM est l’organisme payeur (infections nosocomiales, erreur non fautive, aléa thérapeutique…). Procédure simple, rapide, gratuite et non exclusive d’une action classique.`,
        [`CRCI = conciliation`, `ONIAM = paie`, `Simple, rapide, gratuite`]),
      I('DR', `Qu’est-ce que l’action de groupe en santé ?`,
        `Introduite par la loi du 26 janvier 2016, pour réparer les dommages causés par des produits de santé ; engagée uniquement par une association d’usagers agréée. Deux phases : collective (recevabilité, responsabilité, définition du groupe), puis indemnisation (chaque victime choisit d’adhérer).`,
        [`Association d’usagers agréée`, `Produits de santé`, `2 phases`]),
      // ── Ajouts : consentement, refus de soin, responsabilités, éthique, fragilité ──
      I('TD3', `Un médecin dit à un patient : « Si vous refusez, on ne pourra plus s’occuper de vous aussi bien. » Qu’en penses-tu ? Le patient peut-il changer d’avis ?`,
        `C’est une pression : elle compromet le caractère libre du consentement (L.1111-4). Refuser ou se retirer ne doit avoir aucune conséquence sur la qualité des soins, et le consentement peut être retiré à tout moment. L’étudiant ne contredit pas le médecin devant le patient (réserve, confraternité) mais en parle à sa tutrice ou au cadre, puis éventuellement en analyse de pratique anonymisée.`,
        [`Pression = consentement non libre`, `Aucune conséquence sur la qualité des soins`, `Retirable à tout moment`, `Alerter la tutrice ou le cadre, pas de contradiction devant le patient`]),
      I('RS', `Un patient dit « hors de question » qu’une étudiante pose sa voie veineuse. Que fais-tu ?`,
        `Je respecte son refus, je cherche ses raisons (peur, pudeur, incompréhension), je lui réexplique le soin, je propose que l’infirmier ou la tutrice le réalise, je les préviens et je trace. On ne passe pas outre : le consentement est libre, éclairé et retirable à tout moment (L.1111-4 ; R.4312-14). La pose d’une voie veineuse relève du rôle sur prescription.`,
        [`Respecter le refus`, `Chercher la cause`, `Réexpliquer`, `Alternative : l’IDE ou la tutrice`, `Tracer`]),
      I('RS', `Un enfant de 6 ans refuse catégoriquement une perfusion ; son père dit « tenez-le s’il le faut », sa mère préfère attendre. Que fait l’équipe ?`,
        `Elle cherche d’abord à comprendre la cause du refus (peur, douleur, incompréhension) et en discute avec l’enfant et ses parents. Le consentement du mineur doit être recherché s’il est apte à exprimer sa volonté, avec une information adaptée à son âge et à sa maturité ; les titulaires de l’autorité parentale restent concernés (L.1111-4). Si le soin est indispensable et que tout a échoué, la contrainte reste un dernier recours, proportionné, expliqué et tracé, pas une réponse par défaut.`,
        [`Comprendre la cause du refus`, `Consentement du mineur recherché s’il est apte`, `Autorité parentale maintenue`, `Contrainte = dernier recours, tracée`], [],
        `Tes notes sur l’usage légitime de la force sont incomplètes, et l’âge de 7 ans cité par ton formateur n’est pas une règle absolue : à compléter avec ton cours.`),
      I('RS', `Un adulte lucide refuse un traitement vital. Que prévoit la loi et quels principes éthiques sont en tension ?`,
        `Le médecin doit respecter sa volonté après l’avoir informé des conséquences, tout en mettant tout en œuvre pour le convaincre (il peut faire appel à un autre membre du corps médical) ; le refus est tracé dans le dossier (L.1111-4). Sont en tension l’autonomie (respecter sa décision) et la bienfaisance / non-malfaisance (le protéger malgré lui).`,
        [`Volonté respectée après information`, `Tout mettre en œuvre pour convaincre`, `Refus tracé`, `Autonomie ↔ bienfaisance`]),
      I('TD3', `Une limitation de traitement est envisagée alors que le patient ne peut plus s’exprimer : que prévoit la loi ?`,
        `Une décision médicale prise après une procédure collégiale, en tenant compte d’abord des directives anticipées, puis de la personne de confiance, de la famille ou des proches.`,
        [`Procédure collégiale`, `Directives anticipées d’abord`, `Puis personne de confiance`, `Puis famille ou proches`]),
      I('EX', `Quelles sont les trois formes de responsabilité du soignant ?`,
        `Pénale (infraction), civile (réparation d’un dommage) et disciplinaire (sanction de l’employeur ou de l’Ordre ; pour l’ESI : section disciplinaire de l’IFSI). L’établissement public peut aussi voir sa responsabilité engagée (faute de service).`,
        [`Pénale`, `Civile`, `Disciplinaire`, `Établissement : faute de service`],
        [[`Un étudiant révèle un résultat de sérologie VIH à l’épouse du patient : à quoi s’expose-t-il ?`, `Pénale : violation du secret (1 an, 15 000 €) ; civile : dommages et intérêts pour atteinte à la vie privée ; disciplinaire : section disciplinaire de l’IFSI. Le code de déontologie s’applique aussi aux étudiants, et l’art. 226-13 du Code pénal vise aussi une mission temporaire comme un stage.`]]),
      I('EX', `Le médecin prescrit de l’amoxicilline malgré une allergie à la pénicilline notée au dossier ; la pharmacie valide ; l’infirmière administre et le patient fait une urticaire géante. Qui est responsable, et que fait-on ensuite ?`,
        `Chacun répond de son propre acte dans son domaine : le médecin (prescription), le pharmacien (validation) et l’infirmière (administration sans vérifier le dossier). La validation par la pharmacie ne dispense jamais de vérifier la prescription et le dossier (identité, allergies, dose, voie), ni d’alerter le prescripteur en cas de doute. Ensuite : alerter immédiatement le médecin, surveiller (conscience, respiration, constantes), appliquer le protocole d’urgence ou les actes conservatoires en attendant, tracer fidèlement, déclarer l’événement indésirable et informer le patient.`,
        [`Responsabilité de chacun : prescripteur, pharmacien, IDE`, `La validation pharmacie ne dispense pas de vérifier`, `Alerter le médecin, surveiller`, `Tracer + déclarer`, `Informer le patient`], [],
        `Tes notes marquent ces réponses « à valider » : vérifie la répartition des responsabilités avec ton formateur.`),
      I('EX', `Parmi l’aide à la toilette, l’accompagnement aux déplacements et la pose d’une perfusion d’antalgique, que peut-on confier à l’aide-soignante en collaboration ?`,
        `L’aide à la toilette, l’aide au petit-déjeuner et l’accompagnement aux déplacements : ce sont des actes du rôle propre confiés par l’IDE, sous sa responsabilité. La perfusion d’antalgique relève obligatoirement du rôle sur prescription : elle ne se confie pas.`,
        [`Toilette, repas, déplacements = confiables`, `Perfusion = rôle sur prescription`, `L’IDE reste responsable`], [],
        `Tes notes citent aussi la glycémie capillaire comme acte confiable à l’AS (arrêté du 26/06/2026) : à valider avec ton cours.`),
      I('EX', `La contention : quel rôle, quelles conditions, et quel problème éthique ?`,
        `Elle relève du rôle sur prescription médicale (les barrières de lit relevées en font partie). Elle doit rester exceptionnelle, proportionnée, surveillée, réévaluée et tracée. Elle porte atteinte à la liberté d’aller et venir et à la dignité, et met en tension la bienfaisance (protéger) et l’autonomie (liberté) : l’intérêt du patient n’est « pas forcément » la contention.`,
        [`Rôle prescrit`, `Barrières de lit = contention`, `Exceptionnelle, surveillée, réévaluée, tracée`, `Liberté d’aller et venir, dignité`]),
      I('SP', `Le mari d’une patiente demande à l’infirmière ce que disent les examens. Que fais-tu ?`,
        `Je ne communique rien sans l’accord de la patiente et je l’oriente vers le médecin : le secret appartient au patient, les informations d’ordre médical sont délivrées par le médecin, et seulement aux proches que la patiente accepte d’informer.`,
        [`Rien sans l’accord de la patiente`, `Orienter vers le médecin`, `Le secret appartient au patient`]),
      I('SP', `Un acteur célèbre vient voir sa mère hospitalisée et une étudiante le raconte autour d’elle. Qu’en dis-tu ?`,
        `C’est une violation du secret professionnel : la mère est hospitalisée (information de santé) et la personne est identifiable. Le secret s’impose quelle que soit la notoriété du patient ou de son entourage.`,
        [`Hospitalisation = information de santé`, `Personne identifiable`, `La notoriété ne change rien`]),
      I('TD4', `Face à une difficulté en stage, quels sont les bons réflexes de l’étudiant ?`,
        `En parler au tuteur, au cadre, au formateur ou dans l’évaluation de stage ; aborder la situation en analyse de pratique, de façon anonymisée. On ne cite ni patient, ni lieu, ni soignant, on ne publie pas depuis un lieu de soins et on ne photographie jamais sans autorisation.`,
        [`Tuteur, cadre, formateur`, `Analyse de pratique anonymisée`, `Jamais de patient, lieu ou soignant cités`, `Pas de photo ni de publication depuis le service`]),
      I('ET', `Quels sont les quatre principes du principlisme (Beauchamp et Childress) ? En quoi le rapport Belmont diffère-t-il ?`,
        `Autonomie, bienfaisance, non-malfaisance et justice. Le rapport Belmont (1979) n’en retient que trois : respect des personnes, bienfaisance et justice. Ces principes ont inspiré la loi Kouchner (décision partagée entre le patient et le soignant).`,
        [`Autonomie`, `Bienfaisance`, `Non-malfaisance`, `Justice`, `Belmont = 3 principes`]),
      I('ET', `Que dit Kant de la dignité ? Quelles sont les quatre dimensions du care selon Tronto ?`,
        `Kant : la dignité est absolue, on doit traiter la personne toujours comme une fin et jamais seulement comme un moyen. Tronto : l’attention (caring about), la responsabilité (taking care of), la compétence (care-giving) et la réceptivité (care-receiving). Dans les éthiques du care, l’interdépendance et la vulnérabilité sont au centre : le soin est une relation, pas seulement une technique.`,
        [`Kant : une fin, jamais seulement un moyen`, `Attention`, `Responsabilité`, `Compétence`, `Réceptivité`]),
      I('ET', `Distingue droit, morale, éthique et déontologie.`,
        `Le droit s’impose à tous (avec sanction). La déontologie encadre la profession (code de déontologie des infirmiers). L’éthique questionne : elle aide à décider quand des valeurs entrent en tension. La morale renvoie aux valeurs et aux règles de conduite (le bien et le mal) d’une personne ou d’une société.`,
        [`Droit : s’impose à tous`, `Déontologie : encadre la profession`, `Éthique : questionne`, `Morale : valeurs et règles de conduite`], [],
        `Tes notes donnent la hiérarchie (l’éthique questionne, la déontologie encadre, le droit s’impose) mais pas de définition détaillée de la morale : complète avec ton cours.`),
      I('ET', `Quels événements ont fait naître la bioéthique ? Que sont le code de Nuremberg et le CCNE ?`,
        `Le procès de Nuremberg (1946-1947), l’affaire de la thalidomide et l’étude de Tuskegee (années 1960-1970), puis le rapport Belmont (1979). Le code de Nuremberg (1947) pose le consentement libre, éclairé et rétractable du sujet de recherche. Le CCNE, Comité consultatif national d’éthique créé en 1983, rend des avis sans pouvoir de sanction. La loi Huriet-Sérusclat (20 décembre 1988) encadre les recherches sur la personne ; les lois de bioéthique datent de 1994, 2004, 2011, 2013, 2021.`,
        [`Nuremberg, thalidomide, Tuskegee`, `Belmont 1979`, `Nuremberg = consentement libre, éclairé, rétractable`, `CCNE 1983, consultatif`]),
      I('VU', `Quels sont les 5 critères du phénotype de Fried et comment classe-t-on la fragilité ?`,
        `Perte de poids involontaire (plus de 4,5 kg ou 5 % sur un an), faiblesse musculaire, lenteur de la marche, épuisement, faible activité physique. 0 critère : robuste ; 1 ou 2 : pré-fragile ; 3 ou plus : fragile. Autres outils cités au cours : Rockwood (CFS ≥ 5/9), FRAIL (≥ 3/5), Edmonton.`,
        [`Perte de poids`, `Faiblesse musculaire`, `Lenteur`, `Épuisement`, `Faible activité physique`, `0 / 1-2 / ≥ 3`],
        [[`Une résidente de 86 ans a perdu 5 kg sans le vouloir, marche lentement et se dit épuisée : quel statut ?`, `Trois critères : elle est fragile. (Les chutes et les médicaments ne sont pas des critères du phénotype de Fried.)`]]),
      I('VU', `Quelles actions de prévention de la fragilité l’infirmier peut-il mener ?`,
        `Quatre leviers : prévention des chutes, mobilisation, revue médicamenteuse (la polymédication, soit 5 médicaments ou plus par jour, est un facteur de fragilité et d’iatrogénie, surtout avec des psychotropes) et nutrition (1 à 1,2 g de protéines par kg et par jour chez le sujet âgé, 1,2 à 1,5 g s’il est fragile). On évite les régimes restrictifs et l’alitement prolongé.`,
        [`Chutes`, `Mobilisation`, `Revue médicamenteuse (≥ 5 médicaments)`, `Nutrition protéique 1,2-1,5 g/kg/j si fragile`]),
      I('VU', `Que représente la vulnérabilité au regard de la maltraitance ? Que fais-tu devant un signal faible, par exemple une fille dont le comportement envers sa mère âgée en EHPAD t’inquiète ?`,
        `La vulnérabilité (âge, dépendance, fragilité) est un sur-risque de maltraitance : un signal, même faible, est pris au sérieux. J’observe, je trace les faits sans interprétation et je transmets à l’équipe et au cadre par le circuit interne ; l’évaluation de la situation se fait collectivement.`,
        [`Vulnérabilité = sur-risque`, `Prendre le signal faible au sérieux`, `Tracer les faits, sans interprétation`, `Transmettre au cadre et à l’équipe`], [],
        `Le circuit de signalement est précisé par l’établissement et par la HAS : à vérifier avec ton cours.`),
      I('VU', `Définis la bientraitance.`,
        `Une démarche collective pour identifier l’accompagnement le meilleur possible, dans le respect des droits de la personne, en prévenant la maltraitance. C’est une démarche d’équipe et d’institution, pas seulement une attitude individuelle.`,
        [`Démarche collective`, `Respect des droits de la personne`, `Prévient la maltraitance`], [],
        `Définition issue du cadre de référence de la HAS ; la page de cours correspondante est vide dans tes notes : à compléter avec ton cours.`)
    ]
  };

  const E1 = {
    id: 'E1', ue: 'E.1', name: 'Recherche et données probantes', ico: '🔎',
    blurb: 'Recherche documentaire : question, types de documents, niveaux de preuve, mots-clés, équation de recherche.',
    exam: 'Évaluation à confirmer avec ton formateur (oral d’après ton agenda).',
    note: 'Notes issues du CM en capsules vidéo (Moodle) complétées de repères généraux : vérifie avec le cours si une précision t’est demandée.',
    chapters: { DM: 'Démarche et question', DOC: 'Documents et niveaux de preuve', MOT: 'Mots-clés et MeSH', OUT: 'Outils et équation de recherche' },
    items: [
      I('DM', `Quelles sont les étapes d’une recherche documentaire structurée ?`,
        `1) Formuler son besoin d’information ; 2) choisir concepts et mots-clés ; 3) construire une équation de recherche ; 4) interroger des outils documentaires adaptés ; 5) sélectionner et évaluer les documents ; 6) garder trace de la démarche (carnet de recherche).`,
        [`Besoin`, `Concepts / mots-clés`, `Équation`, `Outils`, `Évaluation`, `Traçabilité`]),
      I('DM', `Pourquoi une information « trouvée » en tête de Google n’est-elle pas une recherche documentée ?`,
        `Elle n’a pas été interrogée pour sa fiabilité ni resituée dans une stratégie de recherche.`,
        [`Pas évaluée`, `Pas de stratégie de recherche`]),
      I('DM', `Quelle est la différence entre QQOQCP et PICOT ?`,
        `QQOQCP (Qui, Quoi, Où, Quand, Comment, Pourquoi) cadre une situation de façon large. PICOT (Population, Intervention, Comparaison, Outcome/résultat, Temps) affine vers une question de recherche comparative exploitable.`,
        [`QQOQCP = cadrer, large`, `PICOT = question de recherche précise`, `Thème large → QQOQCP → PICOT`]),
      I('DOC', `Quels types de documents distingue-t-on et quels sont les points de vigilance ?`,
        `Article scientifique (évalué par les pairs ? revue reconnue ? DOI ?), recommandation de bonnes pratiques (organisme émetteur, date, actualisation), texte juridique (version en vigueur, source officielle comme Légifrance), contenu généré par IA (non citable : à vérifier auprès de sources primaires).`,
        [`Article : pairs, revue, DOI`, `Reco : organisme, date`, `Juridique : version en vigueur, Légifrance`, `IA : jamais citable seule`],
        [[`Pourquoi se méfier de l’IA ?`, `Elle peut sembler crédible tout en étant erronée ou inventée (« hallucination ») : toujours vérifier avec des sources fiables.`]]),
      I('DOC', `Différence entre littérature scientifique et littérature grise ?`,
        `Scientifique : publiée dans des revues à comité de lecture, évaluée par les pairs. Grise : rapports, mémoires, thèses, actes de congrès, documents institutionnels, non publiés en revue classique mais parfois précieux (données récentes, terrain), à évaluer avec prudence.`,
        [`Scientifique = comité de lecture`, `Grise = rapports, thèses, mémoires, congrès`]),
      I('DOC', `Comment évaluer la qualité d’une source ?`,
        `Méthode décrite et rigoureuse ? évalué par les pairs ? biais de publication (les études « positives » sont plus souvent publiées) ? niveau de preuve ? répond-il vraiment à la question posée ?`,
        [`Méthode`, `Pairs`, `Biais de publication`, `Niveau de preuve`, `Adéquation à la question`]),
      I('DOC', `Décris la pyramide des niveaux de preuve (EBM).`,
        `Du plus fort au plus faible : 1) méta-analyses et revues systématiques ; 2) essais contrôlés randomisés ; 3) études de cohorte / cas-témoins ; 4) séries de cas, avis d’experts ; 5) opinion, expérience personnelle.`,
        [`Méta-analyses en haut`, `Essais randomisés`, `Cohortes / cas-témoins`, `Séries de cas, experts`, `Opinion en bas`]),
      I('DOC', `Compare recherche quantitative et recherche qualitative.`,
        `Quantitative : mesurer, comparer, généraliser ; rigueur = validité, fiabilité, reproductibilité. Qualitative : comprendre, explorer un vécu ou un phénomène ; rigueur = crédibilité, transférabilité, cohérence de la démarche. Les deux sont complémentaires.`,
        [`Quanti = mesurer, généraliser`, `Quali = comprendre, explorer`, `Critères de rigueur différents`]),
      I('MOT', `Comment passer d’une question aux mots-clés ? Qu’est-ce que le MeSH ?`,
        `Repérer les concepts essentiels (issus du PICOT), chercher synonymes et équivalents anglais, associer mots libres et descripteurs du thésaurus MeSH (Medical Subject Headings, vocabulaire normalisé utilisé notamment par PubMed), puis faire un tableau de concepts. Un descripteur MeSH regroupe automatiquement les synonymes indexés : recherche plus précise et plus exhaustive.`,
        [`Concepts → synonymes → anglais`, `MeSH = vocabulaire normalisé (PubMed)`, `Tableau de concepts`]),
      I('OUT', `Distingue moteur de recherche, catalogue et base bibliographique, avec un exemple de chacun.`,
        `Moteur de recherche : indexe une très large partie du web sans filtre de qualité (Google, Google Scholar). Catalogue : documents possédés ou accessibles par une bibliothèque (SUDOC, catalogue de BU). Base bibliographique : références scientifiques d’un domaine avec métadonnées normalisées (PubMed/Medline, Cochrane Library, BDSP, CAIRN).`,
        [`Moteur = web sans filtre`, `Catalogue = fonds d’une bibliothèque`, `Base = références scientifiques indexées`]),
      I('OUT', `Quelle différence entre notice bibliographique et texte intégral ? À quoi sert l’ENT ?`,
        `La notice décrit un document (auteur, titre, revue, résumé) sans toujours contenir le texte complet. Le texte intégral est l’accès au document complet, parfois payant, parfois libre (open access). L’ENT donne souvent accès à des ressources payantes via les abonnements de l’établissement : toujours vérifier l’accès par l’ENT avant de chercher une alternative.`,
        [`Notice ≠ texte intégral`, `Open access`, `ENT = ressources payantes de l’établissement`]),
      I('OUT', `Que font les opérateurs booléens ET, OU et SAUF ?`,
        `ET / AND : réduit les résultats (les deux termes présents). OU / OR : élargit (regroupe des synonymes). SAUF / NOT : exclut un terme, à utiliser avec prudence (risque d’exclure des résultats pertinents).`,
        [`ET réduit`, `OU élargit`, `SAUF exclut (prudence)`]),
      I('OUT', `À quoi servent les parenthèses, les guillemets et la troncature ? Donne un exemple d’équation.`,
        `Parenthèses : regrouper les synonymes d’un concept avant de les combiner, ex. (infirmier OR nurse) AND (douleur OR pain). Guillemets : expression exacte, ex. "soins palliatifs". Troncature * : toutes les terminaisons, ex. infirm* trouve infirmier, infirmière, infirmiers.`,
        [`Parenthèses = synonymes groupés`, `Guillemets = expression exacte`, `Troncature * = terminaisons`]),
      I('OUT', `Pourquoi la recherche documentaire est-elle itérative ? À quoi sert le carnet de recherche ?`,
        `Après une première interrogation, on analyse les résultats (trop nombreux ? trop peu ? hors sujet ?), on ajuste l’équation et on consigne chaque étape (mots-clés testés, bases interrogées, nombre de résultats, ajustements). Le carnet permet de justifier sa méthodologie (soutenance, mémoire) et d’éviter de refaire les mêmes recherches infructueuses.`,
        [`Analyser → ajuster → recommencer`, `Carnet : mots-clés, bases, résultats`, `Justifie la méthode`])
    ]
  };

  const B3 = {
    id: 'B3', ue: 'B.3', name: 'Pratiques et interventions infirmières', ico: '🩺',
    blurb: 'Sécurité des soins, hygiène, paramètres vitaux, cœur et poumons, médicament, calculs de dose, prises en soin : tes CM et TD du S1.',
    exam: 'Épreuve écrite individuelle sur table (QRU / QRM) = 70 % de l’UE, le 28/01/2027 d’après ton agenda ; TP noté = 30 %.',
    note: 'Normes et seuils : ceux de TON cours B.3 (ils diffèrent parfois de B.1, par exemple pour les gaz du sang). Pour les calculs, sache toujours expliquer ta démarche (produit en croix, unités). Les points marqués « à valider » le sont aussi dans tes notes.',
    chapters: {
      SEC: 'Sécurité des soins et vigilances', HYG: 'Hygiène et prévention des infections', PV: 'Paramètres vitaux et douleur',
      CV: 'Altération cardiovasculaire', RESP: 'Respiration, oxygène, gaz du sang', MED: 'Médicament : prescription et administration',
      TRA: 'Écrits et transmissions', CALC: 'Calculs de dose et de débit', PRI: 'Prises en soin : coronaire, IC, EP, ECG, asthme'
    },
    items: [
      // ── Sécurité des soins ──
      I('SEC', `Quels sont les 8 principes fondamentaux de la sécurité des soins ?`,
        `Identifier · Vérifier · Prévenir · Respecter · Communiquer · Coopérer · Signaler · Améliorer. Demander de l’aide est un comportement professionnel de sécurité.`,
        [`Identifier`, `Vérifier`, `Prévenir`, `Respecter`, `Communiquer`, `Coopérer`, `Signaler`, `Améliorer`],
        [[`Que doit faire l’étudiant en soins infirmiers face à ses limites ?`, `Connaître ses limites, ne pas réaliser seul un acte non maîtrisé ou non confié, signaler immédiatement une situation dangereuse et transmettre toute erreur ou événement indésirable.`],
         [`Que signifie « pertinence des soins » ?`, `Le bon soin au bon patient, par le bon professionnel, au bon moment. Qualité + sécurité + pertinence = soin écoresponsable.`]]),
      I('SEC', `Distingue l’hémovigilance, la pharmacovigilance, la matériovigilance, l’identitovigilance, l’infectiovigilance et la toxicovigilance.`,
        `Hémovigilance : produits sanguins labiles et transfusion. Pharmacovigilance : médicaments et leurs effets indésirables. Matériovigilance : dispositifs médicaux (ex. tensiomètre défectueux). Identitovigilance : « le bon patient » (erreur de patient). Infectiovigilance : risques infectieux associés aux soins. Toxicovigilance : substances toxiques, intoxications.`,
        [`Hémo = transfusion`, `Pharmaco = médicaments`, `Matério = dispositifs médicaux`, `Identito = bon patient`, `Infectio = infections associées aux soins`, `Toxico = intoxications`]),
      I('SEC', `Distingue erreur, faute, presque accident (near miss) et effet indésirable.`,
        `Erreur : acte non intentionnel, qu’on analyse (comment, pourquoi) ; elle peut devenir une faute si elle traduit un manquement à une règle professionnelle ou de prudence. Faute : manquement à une obligation ou à une règle professionnelle. Near miss : erreur ou situation à risque repérée et corrigée avant d’atteindre le patient (ex. mauvais dosage repéré au double contrôle) ; elle se signale aussi. Effet indésirable : il peut survenir sans erreur (ex. hématome sous anticoagulant correctement prescrit et administré = iatrogénie).`,
        [`Erreur ≠ toujours faute`, `Faute = manquement à une règle`, `Near miss = repéré avant le patient`, `Effet indésirable sans erreur possible`],
        [[`Qu’est-ce que la culture de sécurité des soins ?`, `Des manières de faire et de penser partagées dans l’organisation qui contribuent à la sécurité du patient : réduire les risques et installer des barrières de sécurité, pas être infaillible. Le signalement sert à analyser les causes sans chercher de coupable.`]]),
      // ── Hygiène et prévention des infections ──
      I('HYG', `Quels sont les maillons de la chaîne de transmission des infections ? Distingue contamination, colonisation et infection.`,
        `Agent infectieux → réservoir → porte de sortie → mode de transmission → porte d’entrée → hôte réceptif ; agir sur un seul maillon suffit à interrompre la transmission. Contamination : simple présence du micro-organisme. Colonisation : présence et multiplication sans signe clinique. Infection : le micro-organisme pénètre, se multiplie et entraîne une réaction de l’organisme.`,
        [`Agent → réservoir → porte de sortie → transmission → porte d’entrée → hôte`, `Contamination = présence`, `Colonisation = multiplication sans signe`, `Infection = réaction de l’organisme`]),
      I('HYG', `Que sont les précautions standard et les précautions complémentaires ?`,
        `Standard : le socle, pour tout patient et tout soin, quel que soit le statut infectieux connu ; elles comprennent l’hygiène des mains, et les équipements de protection sont choisis selon le risque d’exposition. Complémentaires : elles s’ajoutent aux précautions standard, selon le mode de transmission (contact, gouttelettes, air) ; elles sont prescrites par le médecin. Le port de gants ne remplace jamais l’hygiène des mains.`,
        [`Standard : tout patient, tout soin`, `EPI selon le risque d’exposition`, `Complémentaires : s’ajoutent, selon le mode de transmission`, `Gants ≠ hygiène des mains`],
        [[`Comment prend-on en charge un patient atteint de Clostridioides difficile ?`, `Précautions complémentaires contact renforcé (EPI, chambre seule, information du patient, gestion du matériel, de l’environnement et des excréta), lavage à l’eau et au savon et produit sporicide : les SHA ne sont pas sporicides.`]]),
      I('HYG', `À quels moments réalise-t-on l’hygiène des mains ? Quand préfère-t-on l’eau et le savon ?`,
        `Avant le contact avec le patient, avant un geste aseptique, après un risque d’exposition à un liquide biologique, après le contact avec le patient et après le contact avec son environnement ; aussi en arrivant et en partant du poste de travail et après utilisation du dossier de soins. Même avec des gants. Si les mains sont déjà mouillées, on les lave au savon (pas de SHA) ; face à Clostridioides difficile, eau et savon.`,
        [`Avant contact, avant geste aseptique`, `Après exposition à un liquide biologique`, `Après contact patient, après contact environnement`, `Même avec des gants`, `Mains mouillées → savon`]),
      I('HYG', `Quelle différence entre nettoyage, désinfection, stérilisation et bionettoyage ?`,
        `Nettoyage : élimine les salissures. Désinfection : élimine ou inactive des micro-organismes sur un milieu inerte. Stérilisation : permet d’obtenir un état stérile. Bionettoyage : nettoyage + désinfection avec un détergent-désinfectant, après le soin et avant la sortie du patient ; on progresse du plus propre vers le plus sale et de haut en bas ; ce n’est pas un geste aseptique.`,
        [`Nettoyer ≠ désinfecter ≠ stériliser`, `Bionettoyage = détergent-désinfectant`, `Du plus propre au plus sale, de haut en bas`]),
      I('HYG', `Quel est le rôle de l’infirmier dans la prévention des infections associées aux soins ?`,
        `Observer · Prévenir · Protéger · Respecter · Informer · Transmettre · Tracer · Alerter. Il observe les signes évocateurs d’une infection, applique les précautions standard et complémentaires, informe le patient et trace et alerte en cas de situation préoccupante. Chaque professionnel est acteur de la prévention.`,
        [`Observer les signes d’infection`, `Appliquer précautions standard et complémentaires`, `Informer le patient`, `Tracer et alerter`]),
      I('HYG', `Un soignant se pique avec une aiguille souillée : quelle est la première conduite à tenir ?`,
        `Ne pas faire saigner de façon agressive, nettoyer immédiatement la zone à l’eau et au savon, puis antisepsie (au moins 5 minutes). Ensuite : contacter rapidement le médecin référent ou les urgences (évaluation du risque et éventuelle prophylaxie), déclarer l’accident du travail et assurer le suivi sérologique. Risques : VHB, VHC, VIH.`,
        [`Pas de pression agressive pour faire saigner`, `Eau + savon, puis antisepsie ≥ 5 min`, `Médecin référent ou urgences`, `Déclarer l’accident du travail, suivi sérologique`], [],
        `Protocole type : à confirmer avec celui donné en cours.`),
      I('HYG', `Quels déchets relèvent de la filière DASRI ?`,
        `Les OPCT (ex. aiguille usagée) sont toujours des DASRI, même sans contact visible avec du sang. Un déchet « mou » est un DASRI s’il est souillé par du sang ou un liquide biologique en quantité suffisante pour risquer de s’écouler, ou s’il provient d’un patient avec un foyer infectieux avéré ou suspecté. Si des DASRI sont mélangés à des déchets ménagers, tout le mélange est requalifié en DASRI.`,
        [`OPCT = toujours DASRI`, `Déchet mou : souillé de façon écoulable ou foyer infectieux`, `Mélange → tout en DASRI`]),
      // ── Paramètres vitaux et douleur ──
      I('PV', `Comment prend-on le pouls radial ? Quelles sont les normes de fréquence cardiaque ?`,
        `Avec l’index et le majeur (jamais le pouce : il a son propre pouls), patient installé et au repos depuis 3 à 5 minutes, en comptant 60 secondes ; on recherche la fréquence, le rythme et l’amplitude ; FC avant PA. Normes : adulte 60 à 80/min ; nourrisson 100 à 150 ; enfant de moins de 6 ans 90 à 120 ; 6-15 ans 70 à 100.`,
        [`Index + majeur, jamais le pouce`, `Repos 3 à 5 min, 60 secondes`, `Fréquence, rythme, amplitude`, `Adulte : 60-80/min`]),
      I('PV', `Quelles sont les règles de la mesure manuelle de la pression artérielle et les contre-indications au bras ?`,
        `Le premier bruit perçu = pression systolique, le dernier = diastolique ; stéthoscope sur l’artère humérale, jamais sous le brassard ; on gonfle à 150-180 mmHg puis on dégonfle lentement ; brassard adapté à la taille du bras ; mesure répétée au plus 2 fois sur le même bras ; brassard et stéthoscope désinfectés entre deux patients. Contre-indications : bras perfusé, fistule artério-veineuse, côté d’une mammectomie avec curage ganglionnaire, membre déficitaire (hémiplégie) : on choisit l’autre bras.`,
        [`1er bruit = systolique, dernier = diastolique`, `Artère humérale, jamais sous le brassard`, `2 mesures max sur le même bras`, `Contre-indications : perfusion, fistule, mammectomie, hémiplégie`],
        [[`Quelle formule usuelle relie la minima à la maxima ?`, `Minima = maxima ÷ 2 + 10 mmHg (ex. 140 → 80).`],
         [`Comment définit-on l’hypotension et l’hypotension orthostatique ?`, `Hypotension : < 100/60 mmHg (femme) ou < 100/70 (homme). Hypotension orthostatique : chute tensionnelle au passage de la position couchée à la position debout.`]]),
      I('PV', `Comment compte-t-on la fréquence respiratoire ? Définis bradypnée, polypnée, apnée, orthopnée et hyperpnée.`,
        `Norme adulte : 12 à 20 cycles par minute (nourrisson 30 à 50) ; on compte pendant 1 minute en observant l’abdomen, sans que le patient s’en aperçoive. Bradypnée : < 10/min. Polypnée : > 20/min. Apnée : arrêt de la respiration. Orthopnée : respiration possible seulement en position assise. Hyperpnée : amplitude augmentée. Eupnée : respiration normale.`,
        [`12 à 20/min, 1 minute, sans prévenir`, `Bradypnée < 10`, `Polypnée > 20`, `Orthopnée = seulement assis`, `Hyperpnée = amplitude ↑`]),
      I('PV', `Quelles sont les valeurs de la température (fébricule, hyperthermie, hypothermie, apyrexie) ? Quelles sont les contre-indications du thermomètre tympanique ?`,
        `Fébricule : 37,5 à 38 °C. Hyperthermie : température centrale > 38 °C. Hypothermie : < 35 °C. Apyrexie : environ 36,5 °C le matin et 37,5 °C le soir. Thermomètre tympanique (mesure de 1 à 2 secondes) : contre-indiqué en cas de bouchon de cérumen, de chirurgie ou cicatrice récente de l’oreille, de pilosité, de drain transtympanique ou d’absence de tympan.`,
        [`Fébricule 37,5-38`, `> 38 hyperthermie`, `< 35 hypothermie`, `Contre-indications : cérumen, chirurgie ou cicatrice de l’oreille, drain`]),
      I('PV', `Que mesure la SpO₂ ? Qu’est-ce qui peut la perturber, et quelle cible vise-t-on chez l’insuffisant respiratoire chronique ?`,
        `La saturation pulsée en oxygène est estimée par l’oxymètre (lumière rouge et infrarouge) ; elle diffère de la SaO₂, mesurée en laboratoire. Perturbations : vernis ou ongle épais, mains froides ou mauvaise circulation, mouvements ou tremblements, variations brutales de lumière ; la mesure est fiable si la courbe est régulière et la valeur stable après 5 à 10 secondes. En cas d’intoxication au monoxyde de carbone, la SpO₂ est trompeuse (on n’en tient pas compte). Cible chez l’insuffisant respiratoire chronique : 88 à 92 %.`,
        [`SpO₂ ≠ SaO₂`, `Vernis, mains froides, mouvements`, `CO : valeur trompeuse`, `Cible 88-92 % si insuffisance respiratoire chronique`], [],
        `L’énoncé du TD 16 citait 95 % pour un patient BPCO : à discuter avec ton enseignant.`),
      I('PV', `Comment évalue-t-on la douleur ? Que signifie TILT ?`,
        `L’évaluation de la douleur est une obligation infirmière ; la douleur est ce que le malade affirme. Auto-évaluation : EVA, EN, EVS. Hétéro-évaluation : DOLOPLUS, ECPA et ALGOPLUS (personne âgée avec troubles de la communication), EVENDOL (enfant) ; elle sous-estime souvent le ressenti réel. TILT : Type de douleur, Intensité, Localisation, Temporalité, complétés par le retentissement sur la vie quotidienne.`,
        [`Obligation infirmière`, `EVA, EN, EVS = auto-évaluation`, `DOLOPLUS, ECPA, ALGOPLUS = personne âgée`, `TILT : type, intensité, localisation, temporalité`]),
      I('PV', `Quels signes observe-t-on dans une douleur aiguë et dans une douleur chronique ? Quel type de douleur évoque une décharge électrique après un zona ?`,
        `Douleur aiguë : augmentation de la FC et de la PA, hypersudation, agitation ou angoisse. Douleur chronique : troubles du sommeil et de l’appétit, fatigue, irritabilité, repli social, symptômes dépressifs. Une douleur en décharge électrique ou en brûlure continue avec fourmillements après un zona est neuropathique (lésion du système nerveux), à distinguer de la douleur nociceptive (stimulation des nocicepteurs : piqûre, coupure).`,
        [`Aiguë : FC ↑, PA ↑, sueurs, agitation`, `Chronique : sommeil, appétit, fatigue, repli, dépression`, `Neuropathique : lésion nerveuse (zona)`]),
      // ── Altération cardiovasculaire (CM7) ──
      I('CV', `Quels sont les facteurs de risque cardiovasculaire non modifiables et modifiables ?`,
        `Non modifiables : l’âge (plus de 50 ans chez l’homme, plus de 60 ans chez la femme), le sexe masculin, l’hérédité cardiovasculaire. Modifiables : dyslipidémies (LDL-cholestérol), tabac (risque multiplié par 5 chez les moins de 50 ans), HTA, diabète, surpoids ou obésité, sédentarité.`,
        [`Âge, sexe masculin, hérédité`, `Dyslipidémies, tabac, HTA`, `Diabète, surpoids, sédentarité`]),
      I('CV', `Décris l’évolution de l’athérosclérose et ses complications selon les territoires.`,
        `Initiation : stries lipidiques (infiltration des LDL dans l’intima) → formation de la plaque (cellules spumeuses) → évolution (noyau nécrotique, chape fibreuse) → rupture de plaque et thrombose. Complications : cerveau → AVC ; cœur → angor et infarctus ; jambes → AOMI avec claudication ; aorte → anévrisme.`,
        [`Stries lipidiques en premier`, `Plaque, noyau nécrotique, chape fibreuse`, `Rupture → thrombose`, `AVC, infarctus, AOMI, anévrisme`]),
      I('CV', `Quelle est la classification de l’HTA ? Où classer 165/95 mmHg ?`,
        `Grade 1 : 140-159 et/ou 90-99. Grade 2 : 160-179 et/ou 100-109. Grade 3 : plus de 180 et/ou plus de 110. Le grade retenu est le plus élevé des deux valeurs : 165/95 correspond à une HTA de grade 2.`,
        [`Grade 1 : 140-159 / 90-99`, `Grade 2 : 160-179 / 100-109`, `Grade 3 : > 180 / > 110`, `On retient le grade le plus élevé`]),
      I('CV', `Explique le SRAA. Quels sont les effets indésirables des IEC et que choisir en cas de toux ?`,
        `La rénine (sécrétée par le rein) active la cascade : l’enzyme de conversion transforme l’angiotensine I en angiotensine II, qui provoque une vasoconstriction et stimule l’aldostérone → rétention hydrosodée, augmentation de la volémie et de la PA. Les IEC bloquent l’enzyme de conversion : toux sèche (10 à 15 %), angio-œdème, hyperkaliémie ; en cas d’intolérance, les ARA II sont préférés (pas de toux).`,
        [`Rénine → angiotensine I → II (enzyme de conversion)`, `Vasoconstriction + aldostérone`, `IEC : toux sèche, angio-œdème, hyperkaliémie`, `Toux → ARA II`],
        [[`Effets indésirables des autres antihypertenseurs ? Que dit-on de la grossesse ?`, `Inhibiteurs calciques : œdèmes des chevilles. Bêtabloquants : bradycardie, bronchospasme. Anti-minéralocorticoïdes : hyperkaliémie, gynécomastie. Chez la femme enceinte, IEC, ARA II, thiazidiques et anti-minéralocorticoïdes sont contre-indiqués.`]]),
      I('CV', `Distingue signes de congestion et signes d’hypoperfusion. Quels signes orientent vers un état de choc ?`,
        `Congestion : œdèmes déclives bilatéraux, turgescence jugulaire. Hypoperfusion : extrémités froides, recoloration capillaire retardée (> 3 s), pâleur, cyanose, marbrures. Le choc se reconnaît à l’association de signes d’hypoperfusion (marbrures, extrémités froides, tachycardie > 100/min, recoloration > 3 s, confusion ou agitation) : l’hypotension peut manquer au début. On alerte immédiatement.`,
        [`Congestion : œdèmes, jugulaires`, `Hypoperfusion : extrémités froides, marbrures, TRC > 3 s`, `Choc = association de signes, pas la PA seule`, `Alerter immédiatement`]),
      I('CV', `Quels signes évoquent une insuffisance cardiaque et lesquels sont des signes d’alerte ?`,
        `Dyspnée d’effort puis de repos, orthopnée ; œdèmes des membres inférieurs et turgescence jugulaire ; prise de poids de 2 kg ou plus en 3 jours ; crépitants pulmonaires. Signes d’alerte : dyspnée de repos, SpO₂ < 92 %, tachypnée, hypotension, confusion → alerter rapidement.`,
        [`Dyspnée, orthopnée`, `OMI, jugulaires`, `Poids ≥ 2 kg en 3 jours`, `Alerte : dyspnée de repos, SpO₂ < 92 %, confusion`]),
      I('CV', `Où se situent les foyers d’auscultation cardiaque ?`,
        `Mitral (apex) : 5e espace intercostal gauche sur la ligne médio-claviculaire. Aortique : 2e EIC droit. Pulmonaire : 2e EIC gauche. Tricuspide : 4e-5e EIC gauche, au bord du sternum. L’auscultation permet de repérer un souffle, pas de poser le diagnostic.`,
        [`Mitral : 5e EIC gauche, médio-claviculaire`, `Aortique : 2e EIC droit`, `Pulmonaire : 2e EIC gauche`, `Tricuspide : 4e-5e EIC gauche, sternum`]),
      // ── Respiration, oxygène, gaz du sang ──
      I('RESP', `Quels signes alertent d’une détresse respiratoire ? Quelle position adopter ?`,
        `Tirage intercostal, tirage sterno-cléido-mastoïdien, balancement thoraco-abdominal, cyanose des extrémités et des muqueuses (normalement seul le diaphragme est actif à l’inspiration). Position assise ou demi-assise (dossier relevé à plus de 30°), qui facilite l’ampliation thoracique.`,
        [`Tirage intercostal et sterno-cléido-mastoïdien`, `Balancement thoraco-abdominal`, `Cyanose`, `Assis ou demi-assis > 30°`]),
      I('RESP', `Compare les dispositifs d’oxygénothérapie conventionnelle. Quelle est la FiO₂ de l’air ?`,
        `Lunettes : 0,1 à 5-6 L/min, FiO₂ 24 à 50 %. Masque simple : 5 à 10 L/min, FiO₂ 40 à 60 %. Masque à haute concentration : 9 à 15 L/min, FiO₂ 60 à 98 %. Air ambiant : FiO₂ 0,21 (21 %), soit 78 % de diazote, 21 % d’oxygène et 1 % d’autres gaz.`,
        [`Lunettes : ≤ 6 L/min, 24-50 %`, `Masque simple : 5-10 L/min, 40-60 %`, `Haute concentration : 9-15 L/min, 60-98 %`, `Air : 21 %`]),
      I('RESP', `Oxygénothérapie : qui fait quoi (prescription, délégation à l’aide-soignant) et quels risques ?`,
        `L’oxygène est un médicament : il nécessite une prescription. L’initiation et la modification du débit relèvent du rôle prescrit et ne sont pas délégables ; la surveillance relève du rôle propre et peut être déléguée à l’aide-soignant (qui peut aussi prendre les paramètres vitaux, monter un débitmètre sur une prise, changer des lunettes sans toucher au débit). L’oxygène est comburant (pas de flamme, pas de corps gras) et sort froid et sec. Chez le BPCO hypercapnique chronique, trop d’O₂ freine la ventilation (CO₂, acidose, somnolence, coma) : on titre pour viser 88-92 %, sans jamais priver d’O₂ un patient hypoxémique.`,
        [`O₂ = médicament, prescription`, `Modifier le débit : non délégable`, `Surveillance : rôle propre, délégable`, `Comburant`, `BPCO : cible 88-92 %`], [],
        `L’énoncé du TD 16 citait 95 % pour la cible chez le BPCO : à discuter avec ton enseignant.`),
      I('RESP', `Gaz du sang artériel : indications, ponction et seuils de PaO₂ ?`,
        `Indications : suspicion de trouble acido-basique, caractérisation d’une insuffisance respiratoire, état de choc (lactates). Site privilégié : l’artère radiale ; un test d’Allen négatif (retour de coloration en plus de 15 s ; normal entre 10 et 15 s) contre-indique la ponction radiale ; le test de Barbeau a le même objectif chez la personne inconsciente ou non coopérative ; seringue spécifique sans vide ; acte du rôle sur prescription. PaO₂ : normoxémie 80 à 100 mmHg, hypoxémie < 80, hyperoxémie > 100.`,
        [`Trouble acido-basique, insuffisance respiratoire, choc`, `Artère radiale, test d’Allen`, `Rôle sur prescription`, `PaO₂ 80-100 ; < 80 = hypoxémie`], [],
        `Dans le cours B.3 : PaCO₂ 36-44 mmHg et HCO₃⁻ 22-26 mmol/L ; le CM de B.1 donne des valeurs un peu différentes. Retiens celles de chaque cours.`),
      I('RESP', `Comment interprète-t-on un gaz du sang ? Que dire de : pH 7,29, PaCO₂ 72, PaO₂ 58, HCO₃⁻ 34 ?`,
        `En 3 temps : 1) pH (< 7,35 acidose ; > 7,45 alcalose) ; 2) PaCO₂ pour l’origine respiratoire et HCO₃⁻ pour l’origine métabolique, puis la compensation ; 3) PaO₂ pour l’oxygénation. Ici : acidose respiratoire (hypercapnie) avec hypoxémie ; HCO₃⁻ élevés = compensation rénale. L’interprétation sert le raisonnement clinique, pas le diagnostic.`,
        [`pH d’abord`, `PaCO₂ = respiratoire, HCO₃⁻ = métabolique`, `Compensation`, `PaO₂ = oxygénation`],
        [[`Patient somnolent sous morphiniques : FR 10/min, pH 7,31, PaCO₂ 51, HCO₃⁻ 30. Interprétation ?`, `Acidose respiratoire (hypoventilation → accumulation de CO₂) avec compensation rénale en cours (HCO₃⁻ déjà élevés).`],
         [`Et une acidose métabolique ?`, `pH bas et HCO₃⁻ bas.`]], 
        `Normes de gaz du sang : celles de ton cours B.3 (voir la fiche précédente), pas celles de B.1.`),
      // ── Médicament : prescription et administration ──
      I('MED', `Que doit contenir une ordonnance exploitable ? Que fais-tu devant « Antibiotique : 1 comprimé matin et soir », sans prescripteur identifiable ni date ni dosage ?`,
        `Le prescripteur (nom, qualité, n° RPPS), la date, le patient (nom, prénom, date de naissance : la chambre n’est pas une identité), le médicament (DCI, dosage, forme, voie), la posologie (dose, rythme, durée) et la signature. Devant une prescription incomplète : je n’administre pas, je demande une prescription complète au prescripteur ou au médecin du service, je trace et j’informe le cadre. Règle du TD : « ne pas interpréter » ; un doute n’est jamais compensé par une supposition. « Antibiotique » n’est pas une DCI.`,
        [`Prescripteur, date, patient`, `DCI, dosage, forme, voie`, `Posologie : dose, rythme, durée`, `Signature`, `Incomplet → je n’administre pas`],
        [[`Attention aux noms de marque : que contient l’Augmentin® ?`, `Amoxicilline + acide clavulanique (deux molécules).`]]),
      I('MED', `Que fais-tu devant une prescription à haut risque incomplète : KCl « 1 ampoule dans la perfusion sur 4 h », ou insuline « selon glycémie » sans schéma ?`,
        `KCl : je ne prépare ni n’administre, je demande une prescription complète, je vérifie la kaliémie et je fais un double contrôle ; le KCl n’est jamais pur ni en injection directe (risque d’arrêt cardiaque). Insuline sans schéma : je n’injecte pas, je mesure et trace la glycémie capillaire, je demande au médecin le schéma écrit ou le protocole du service et je surveille le risque d’hypoglycémie. On n’invente jamais une dose ou une modalité manquante.`,
        [`KCl : jamais pur, jamais en injection directe`, `Prescription complète + double contrôle`, `Insuline : pas de schéma, pas d’injection`, `Glycémie tracée, schéma ou protocole demandé`]),
      I('MED', `Quelles sont les règles des 5B et des 7B ? Qui prépare et administre ?`,
        `5B (HAS) : bon médicament, bon patient, bonne dose, bonne voie, bon moment. 7B : on ajoute bon débit et bon professionnel. Le même infirmier prépare et administre ; double vérification indépendante en cas de doute sur un calcul ou une dilution, et systématiquement pour certains médicaments à haut risque. Chaque administration est tracée.`,
        [`5B : médicament, patient, dose, voie, moment`, `7B : + débit, professionnel`, `Même IDE prépare et administre`, `Double vérification pour les médicaments à haut risque`]),
      I('MED', `Quelles sont les étapes de l’identitovigilance avant d’administrer ? Que fais-tu si tu es interrompu pendant une préparation à risque ?`,
        `Quatre temps : faire épeler nom, prénom et date de naissance sans suggérer la réponse (question ouverte) ; vérifier la concordance avec le bracelet ; confronter l’identité avec la prescription et le dossier ; tracer. On identifie par le nom, jamais par la chambre ni la pathologie. Après une interruption, je reprends toutes les vérifications depuis le début, avec un double contrôle pour un morphinique ou un anticoagulant ; tout produit préparé est étiqueté.`,
        [`Faire épeler, sans suggérer`, `Bracelet`, `Confronter prescription et dossier`, `Tracer`, `Interruption → tout recommencer`]),
      I('MED', `Que trace-t-on après l’administration d’un médicament ?`,
        `La dose et l’heure réelles d’administration, le contrôle d’identité réalisé, la voie et le débit effectivement utilisés, le produit, le dosage et le n° de lot si requis. On trace après l’acte, jamais à l’avance. En cas d’anomalie : effet indésirable observé, décision de différer avec justification, information transmise, non-administration et motif.`,
        [`Dose et heure réelles`, `Identité contrôlée`, `Voie et débit réels`, `Après l’acte, jamais avant`, `Anomalie, report ou non-administration tracés`]),
      I('MED', `Mme B. a reçu du paracétamol à 4 h 30 ; la prescription indique « toutes les 6 heures si douleur ». À 7 h 30 elle a mal (EN 6/10). Que fais-tu ?`,
        `Je ne donne pas maintenant (prochaine prise possible à 10 h 30), j’alerte le médecin pour la douleur et je propose des mesures non médicamenteuses, puis je réévalue avec la même échelle. On respecte l’intervalle fixé par le prescripteur : risque de surdosage et de toxicité hépatique.`,
        [`4 h 30 + 6 h = 10 h 30`, `Alerter le médecin`, `Mesures non médicamenteuses`, `Réévaluer avec la même échelle`]),
      I('MED', `Après une injection de morphine, quels signes évoquent une dépression respiratoire et que fais-tu ?`,
        `Signes : somnolence importante, FR ≤ 10/min (respiration lente ou peu ample), score de sédation ≥ 2, SpO₂ basse ou en baisse, cyanose ; aussi hypotension, bradycardie, myosis, vomissements (risque d’inhalation). Actions : stimuler le patient, vérifier sa respiration et ne pas le laisser seul ; arrêter toute nouvelle administration ; alerter immédiatement le médecin (méthode SAED) ; surveiller en continu FR, SpO₂, sédation, PA et FC. L’antidote (naloxone) et l’oxygène hors urgence vitale relèvent d’une prescription ou d’un protocole ; la naloxone agit moins longtemps que la morphine, d’où une surveillance prolongée. On soigne d’abord, on signale ensuite.`,
        [`Somnolence, FR ≤ 10, sédation ≥ 2, SpO₂ ↓`, `Stimuler, ne pas laisser seul`, `Stop morphine, alerter`, `Surveillance continue et prolongée (naloxone)`],
        [[`Que signifie SAED dans une transmission orale urgente ?`, `Situation (qui j’appelle et pourquoi), Antécédents et traitement, Évaluation (constantes, hypothèse sans diagnostic), Demande (conduite à tenir, surveillance).`]]),
      I('MED', `Explique ADME, pharmacocinétique et pharmacodynamie. Quelle étape n’existe pas en voie intraveineuse ?`,
        `Pharmacocinétique : ce que l’organisme fait au médicament (ADME : absorption, distribution, métabolisme surtout hépatique, élimination surtout rénale et biliaire). Pharmacodynamie : ce que le médicament fait à l’organisme (mécanisme d’action, effets thérapeutiques et indésirables). En IV, il n’y a pas d’absorption : biodisponibilité théorique de 100 % et début d’action le plus rapide, d’où une surveillance anticipée, continue et poursuivie après l’administration.`,
        [`PK = organisme → médicament (ADME)`, `PD = médicament → organisme`, `IV : pas d’absorption`, `Surveillance anticipée et prolongée`]),
      I('MED', `Une personne demande à écraser son comprimé à libération prolongée. Que réponds-tu ?`,
        `Non : l’écrasement libère toute la dose d’un coup (risque de surdosage). On n’écrase jamais une forme LP, gastro-résistante ou sublinguale sans validation : je vérifie la forme exacte et le RCP, je contacte le pharmacien puis le médecin prescripteur pour une alternative, et je trace la demande, les avis et la décision.`,
        [`Non : toute la dose d’un coup`, `Vérifier la forme et le RCP`, `Pharmacien, puis médecin`, `Tracer`]),
      // ── Écrits et transmissions ──
      I('TRA', `Que mettent D, A et R dans une transmission ciblée ? Comment formuler la cible pour un diabétique pâle et en sueurs à 0,58 g/L ?`,
        `D = ce que j’observe, ce que dit le patient, les mesures chiffrées. A = ce qui a été fait ou proposé (y compris les professionnels prévenus). R = évolution après les actions (valeurs de contrôle, ressenti, ou « pas de résultat à ce stade »). Une cible est un problème ou un besoin du patient, courte et factuelle, jamais une action : « Hypoglycémie », pas « resucrer ». Exemple de R : glycémie de contrôle à 0,82 g/L après 15 minutes et patient moins faible.`,
        [`D = observé, dit, mesuré`, `A = actions faites ou proposées`, `R = évolution après les actions`, `Cible = problème, jamais une action`], [],
        `Le seuil d’hypoglycémie (< 0,70 g/L) est hors cours dans tes notes : à valider.`),
      I('TRA', `Quelles règles pour les écrits professionnels ? Que signifie un soin non tracé ?`,
        `Ils sont horodatés et identifiés, lisibles, précis, objectifs et factuels, rédigés rapidement après le soin ; jamais de jugement de valeur, d’effacement ou de correction non conforme, d’information inexacte. Ils ont une valeur juridique. Un soin non tracé est considéré comme non fait : la traçabilité assure la continuité des soins, la sécurité, la valeur juridique, la communication entre professionnels et la qualité.`,
        [`Horodatés, identifiés`, `Factuels, objectifs, sans jugement`, `Rédigés rapidement après le soin`, `Non tracé = non fait`]),
      // ── Calculs de dose et de débit ──
      I('CALC', `Quelles formules utilises-tu pour un débit en gouttes par minute et en mL/h ?`,
        `Débit (gouttes/min) = volume total (mL) × nombre de gouttes par mL (20 avec un perfuseur standard) ÷ durée en minutes. Débit (mL/h) = volume total (mL) ÷ durée en heures. On utilise la durée de passage, pas l’intervalle entre deux prises. Les doses se calculent par produit en croix.`,
        [`Gouttes/min = mL × 20 ÷ minutes`, `mL/h = mL ÷ heures`, `Durée de passage, pas intervalle entre prises`, `Produit en croix pour les doses`]),
      I('CALC', `Gentalline prescrite à 60 mg ; ampoule de 80 mg dans 2 mL. Quel volume prélèves-tu ?`,
        `60 × 2 ÷ 80 = 1,5 mL (produit en croix).`,
        [`60 × 2 ÷ 80`, `1,5 mL`]),
      I('CALC', `Gentalline 60 mg (1,5 mL) dans 50 mL de G5 %, à passer en 20 minutes avec un perfuseur à 20 gouttes/mL. Quel est le débit par gravité ?`,
        `Volume total : 51,5 mL. Débit = 51,5 × 20 ÷ 20 = 51,5, soit 52 gouttes/min. Il faut utiliser la durée de passage (20 min), pas l’intervalle entre deux prises (8 h). En mL/h : 51,5 × 3 = 154,5 mL/h.`,
        [`Volume total 51,5 mL`, `51,5 × 20 ÷ 20`, `52 gouttes/min`, `154,5 mL/h`]),
      I('CALC', `Glucosé 5 % 250 mL en 12 heures, perfuseur à 20 gouttes/mL : quel est le débit ?`,
        `250 × 20 = 5 000 gouttes ; 12 h × 60 = 720 min ; 5 000 ÷ 720 = 6,94, arrondi à 7 gouttes/min.`,
        [`5 000 gouttes`, `720 min`, `7 gouttes/min`]),
      I('CALC', `Héparine prescrite à 32 000 UI par 24 heures au pousse-seringue : quelle dose horaire ? Et une seringue de 48 mL à passer en 8 heures : quel débit ?`,
        `32 000 UI ÷ 24 h ≈ 1 333 UI/h. 48 mL ÷ 8 h = 6 mL/h. L’important est le raisonnement : volume ÷ durée, en vérifiant les unités (UI/h, mL/h).`,
        [`32 000 ÷ 24 = 1 333 UI/h`, `48 ÷ 8 = 6 mL/h`, `Vérifier les unités`], [],
        `Le volume de seringue et la concentration viennent d’un dictaphone peu lisible dans tes notes : retiens surtout la méthode.`),
      I('CALC', `Claforan 650 mg ; flacon de poudre dosé à 1 g reconstitué dans 10 mL. Quel volume prélèves-tu ? Puis quel débit en pompe si 56,5 mL passent en 20 minutes ?`,
        `650 × 10 ÷ 1 000 = 6,5 mL (concentration 100 mg/mL) ; avec la poche de 50 mL, le volume total est de 56,5 mL. Débit en pompe : 56,5 ÷ (20/60) = 56,5 × 3 = 169,5 mL/h. En gouttes/min : 56,5 × 20 ÷ 20 = 56,5, soit 57 gouttes/min.`,
        [`6,5 mL`, `Volume total 56,5 mL`, `169,5 mL/h`, `57 gouttes/min`]),
      I('CALC', `Glucose 5 % 500 mL + 1 g de NaCl, avec des ampoules de NaCl à 20 % : quel volume prélèves-tu ? Puis quel débit pour la poche de 505 mL en 8 heures (20 gouttes/mL) ?`,
        `NaCl à 20 % = 0,20 g/mL, donc 1 ÷ 0,20 = 5 mL ; volume total 500 + 5 = 505 mL. Débit : 505 × 20 ÷ (8 × 60) = 10 100 ÷ 480 ≈ 21 gouttes/min (environ 63 mL/h).`,
        [`1 ÷ 0,20 = 5 mL`, `Total 505 mL`, `21 gouttes/min`, `≈ 63 mL/h`]),
      I('CALC', `Prednisolone 1 mg/kg per os pour une patiente de 60 kg, comprimés orodispersibles à 20 mg : combien en administres-tu ?`,
        `1 mg/kg × 60 kg = 60 mg ; 60 ÷ 20 = 3 comprimés. Surveillances : glycémie, PA, humeur et sommeil ; la cure orale courte (5 jours) n’a pas les effets d’un traitement prolongé.`,
        [`60 mg`, `3 comprimés`, `Surveiller glycémie, PA, humeur, sommeil`]),
      // ── Prises en soin ──
      I('PRI', `Une douleur thoracique réapparaît chez un patient hospitalisé pour suspicion de syndrome coronarien. Quelles sont les actions prioritaires ?`,
        `L’installer au repos et réévaluer immédiatement la douleur (siège, type, irradiation, EVA, heure de début) ; recueillir les paramètres vitaux (PA, FC, FR, SpO₂) ; prévenir rapidement l’infirmier responsable et/ou le médecin ; préparer l’ECG prescrit ; rester auprès du patient. La récidive signe une ischémie qui persiste : le muscle cardiaque risque la nécrose.`,
        [`Repos + réévaluer la douleur`, `PA, FC, FR, SpO₂`, `Prévenir IDE et/ou médecin`, `Préparer l’ECG, rester auprès du patient`]),
      I('PRI', `SCA suspect, douleur à 5/10, SpO₂ à 94 % en air ambiant ; la prescription indique « O₂ 2 L/min par lunettes si SpO₂ < 90 % ». Que fais-tu ?`,
        `Pas d’indication d’oxygène (94 % > 90 %) : je surveille la SpO₂ de façon rapprochée et je transmets. L’oxygène est un médicament : il s’administre sur prescription et selon la SpO₂ ; quand la saturation est correcte, il n’apporte pas de bénéfice et peut être délétère. L’administration est tracée.`,
        [`94 % > 90 % : pas d’O₂`, `Surveillance rapprochée`, `O₂ = médicament, selon la prescription`, `Tracer`]),
      I('PRI', `Avant d’administrer de la trinitrine sublinguale à un patient douloureux, que fais-tu ?`,
        `Je contrôle la pression artérielle (pas de trinitrine en cas d’hypotension), je vérifie les allergies et contre-indications, je recherche la prise récente d’un médicament contre les troubles de l’érection, je vérifie la prescription (identité, dose, voie), j’installe le patient assis (risque d’hypotension) et je réévalue la douleur et la tolérance après l’administration. L’oxygène n’est pas systématique : il dépend de la prescription et de la SpO₂.`,
        [`PA avant`, `Allergies, contre-indications`, `Médicament des troubles de l’érection`, `Patient assis`, `Réévaluer douleur et tolérance`]),
      I('PRI', `À 15 h 23, un patient suivi pour SCA a une PA à 104/68 (138/84 à l’admission), une FC à 96, une FR à 22, une SpO₂ à 94 %, la peau pâle et moite, et une douleur à 5/10 identique à celle du matin. Que traduisent ces données ?`,
        `Une ischémie qui persiste avec retentissement : la PA baisse, la FC monte, la FR augmente (l’organisme compense) → alerte immédiate. Je reste auprès du patient, je prends les constantes, j’alerte, et l’ECG et le traitement se font sur prescription. Facteur déclenchant retenu dans la situation : le lever malgré le repos strict.`,
        [`PA ↓, FC ↑, FR ↑`, `Peau pâle et moite`, `Alerte immédiate`, `Constantes, ECG et traitement sur prescription`]),
      I('PRI', `Quels conseils d’éducation donner à la sortie après la pose d’un stent coronaire ?`,
        `Ne jamais arrêter la double antiagrégation sans l’avis du cardiologue (risque de thrombose du stent) ; appeler le 15 si la douleur thoracique dure ou s’accompagne de sueurs, d’essoufflement ou de malaise ; arrêt total du tabac avec une aide au sevrage ; reprise progressive de l’activité physique avec réadaptation cardiovasculaire ; éviter l’automédication (AINS + antiagrégants = risque hémorragique). L’arrêt de travail et la reprise sont décidés avec le médecin et le médecin du travail.`,
        [`Double antiagrégation : jamais d’arrêt sans cardiologue`, `Douleur durable → 15`, `Arrêt du tabac`, `Activité progressive, réadaptation`, `Pas d’automédication (AINS)`]),
      I('PRI', `Que traduit un BNP à 1 100 pg/mL chez une patiente en insuffisance cardiaque ? Quelles surveillances sous furosémide ?`,
        `Une insuffisance cardiaque décompensée : le BNP est sécrété par les ventricules quand leurs parois sont étirées (« le cœur parle quand il va mal ») ; 1 100 est très au-dessus des seuils (zone grise 100-300 ou 100-400 pg/mL). Furosémide (diurétique de l’anse, à donner le matin) : surveiller la diurèse et le poids, la dyspnée, l’orthopnée et les œdèmes (efficacité), la PA (hypotension orthostatique), la kaliémie, la natrémie et la créatininémie ; effets indésirables : hypokaliémie, hyponatrémie, hypotension, déshydratation, insuffisance rénale fonctionnelle.`,
        [`BNP très élevé = IC décompensée`, `Diurèse et poids`, `PA (orthostatique)`, `Kaliémie, natrémie, créatininémie`],
        [[`Pourquoi surveiller la kaliémie sous furosémide chez un coronarien ?`, `Il est hypokaliémiant, et une hypokaliémie expose à des troubles graves du rythme cardiaque (le potassium joue un rôle essentiel dans l’activité électrique du cœur). Norme : 3,5 à 5 mmol/L.`],
         [`Le bisoprolol prescrit à la patiente : effet attendu et surveillance ?`, `Bêtabloquant : ralentit le cœur et diminue son travail et sa consommation d’oxygène (explique une FC à 65). Surveiller FC et PA avant la prise ; ne pas arrêter brutalement ; effets indésirables : bradycardie, hypotension, asthénie, extrémités froides.`]]),
      I('PRI', `Quels signes évoquent une embolie pulmonaire ? Quel facteur favorisant chez une patiente hospitalisée depuis 10 jours, et quelle surveillance sous héparine ?`,
        `Signes : dyspnée ou polypnée brutale, douleur thoracique brutale, malaise ou syncope, signes de choc (baisse de la PA, tachycardie) ; l’EP peut donner une insuffisance cardiaque droite aiguë (turgescence jugulaire). Facteur favorisant retenu en TD : l’immobilisation liée à l’hospitalisation ; prévention habituelle : anticoagulant préventif, contention veineuse, lever précoce. Sous héparine : TCA, activité anti-Xa et plaquettes ; sous-dosage = inefficacité et risque de récidive, surdosage = risque hémorragique.`,
        [`Dyspnée et douleur thoracique brutales`, `Malaise, choc`, `Immobilisation = facteur favorisant`, `Héparine : TCA, anti-Xa, plaquettes`]),
      I('PRI', `Où place-t-on les électrodes des membres pour un ECG ?`,
        `Rouge : membre supérieur droit ; jaune : membre supérieur gauche ; vert : membre inférieur gauche ; noir : membre inférieur droit. Moyen mnémotechnique vu en TD : « le sang sur le bitume et le soleil sur la prairie » (rouge et noir à droite, jaune et vert à gauche ; en haut les mains, en bas les chevilles).`,
        [`Rouge : bras droit`, `Jaune : bras gauche`, `Vert : jambe gauche`, `Noir : jambe droite`], [],
        `Tes notes ne donnent explicitement que le rouge et le jaune : vérifie vert et noir sur le schéma de ton cours.`),
      I('PRI', `Une jeune femme asthmatique arrive aux urgences en crise (assise penchée en avant, phrases courtes, sifflements). Quels soins relèvent du rôle propre ? Que penser d’un DEP à 170 L/min pour une valeur de référence de 450 ?`,
        `Rôle propre : la garder assise ou demi-assise, penchée en avant ; rassurer, parler calmement avec des questions courtes et la faire parler le moins possible ; surveiller FR, FC, PA, SpO₂, température et signes de gravité (parole, tirage, cyanose, sueurs) ; recueillir les traitements pris, l’heure de la dernière Ventoline® et l’arrêt du Symbicort®. Sur prescription : oxygène, aérosols de salbutamol et d’ipratropium, prednisolone, bilan. On ne dit jamais que « tout va bien se passer ». DEP : 170 ÷ 450 ≈ 38 % de la valeur de référence, soit un critère de gravité (≤ 50 %) ; un seul critère sévère suffit.`,
        [`Position assise penchée en avant`, `Rassurer, questions courtes`, `Surveiller constantes et signes de gravité`, `O₂, aérosols, prednisolone : sur prescription`, `DEP ≤ 50 % = sévère`]),
      I('PRI', `Une patiente prend son Symbicort Turbuhaler® en soufflant dans l’embout, en inspirant lentement, sans se rincer la bouche, et dit l’utiliser « d’habitude avec la chambre d’inhalation ». Quelle correction apportes-tu ?`,
        `C’est un inhalateur de poudre : jamais de chambre d’inhalation (réservée aux aérosols-doseurs, comme la Ventoline®). Technique : expirer à fond hors de l’embout, inspirer fort et profondément, se rincer la bouche et recracher. On fait une démonstration, puis la patiente refait le geste et reformule (éducation thérapeutique).`,
        [`Poudre : pas de chambre d’inhalation`, `Expirer hors de l’embout, inspirer fort et profond`, `Rinçage de bouche`, `Démonstration puis reformulation`])
    ]
  };

  const sets = [B1, B3, A2, E1];
  // Identifiants stables : id du set + rang (2 chiffres, ou 3 au-delà de 99).
  sets.forEach(s => s.items.forEach((it, i) => { it.id = s.id + '-' + String(i + 1).padStart(2, '0'); it.set = s.id; }));

  // Sigles : affichés en petit sous la question (ceux de la question) ou dans le bloc réponse (ceux de la réponse).
  // Détection automatique dans le texte (majuscules respectées, mot entier). Pas de « IV / IM / SC » : trop courants et ambigus.
  const glossary = {
    'ATP': `adénosine triphosphate`, 'VES': `volume d’éjection systolique`, 'FC': `fréquence cardiaque`, 'Qc': `débit cardiaque`,
    'FE': `fraction d’éjection`, 'VTD': `volume télédiastolique`, 'VTS': `volume télésystolique`, 'PA': `pression artérielle`,
    'HTA': `hypertension artérielle`, 'IASP': `Association internationale pour l’étude de la douleur`,
    'EN': `échelle numérique`, 'EVA': `échelle visuelle analogique`,
    'EVENDOL': `échelle d’hétéro-évaluation de la douleur de l’enfant`,
    'FLACC': `échelle comportementale d’hétéro-évaluation de la douleur (Face, Legs, Activity, Cry, Consolability)`,
    'FPS-R': `échelle des visages (Faces Pain Scale – Revised)`,
    'IVA': `artère interventriculaire antérieure`, 'SCA': `syndrome coronarien aigu`, 'ECG': `électrocardiogramme`,
    'IEC': `inhibiteur de l’enzyme de conversion`, 'AOMI': `artériopathie oblitérante des membres inférieurs`,
    'IPS': `index de pression systolique`, 'IC': `insuffisance cardiaque`, 'NYHA': `New York Heart Association (classification de l’insuffisance cardiaque)`,
    'FEVG': `fraction d’éjection du ventricule gauche`, 'ARA II': `antagoniste des récepteurs de l’angiotensine II`,
    'AINS': `anti-inflammatoires non stéroïdiens`, 'BNP': `peptide natriurétique de type B`,
    'NT-proBNP': `forme N-terminale du précurseur du BNP`, 'OAP': `œdème aigu du poumon`, 'OMI': `œdèmes des membres inférieurs`,
    'TVP': `thrombose veineuse profonde`, 'EP': `embolie pulmonaire`, 'MTEV': `maladie thrombo-embolique veineuse`,
    'FA': `fibrillation atriale`, 'QRS': `complexe ventriculaire de l’ECG`, 'AVK': `antivitamine K`,
    'INR': `rapport international normalisé (surveillance des AVK)`, 'RAC': `rétrécissement aortique calcifié`,
    'ETT': `échocardiographie transthoracique`, 'TAVI': `implantation d’une valve aortique par cathéter (Transcatheter Aortic Valve Implantation)`,
    'PaO₂': `pression partielle artérielle en oxygène`, 'PaCO₂': `pression partielle artérielle en gaz carbonique`,
    'PCO₂': `pression partielle en gaz carbonique`, 'SaO₂': `saturation artérielle en oxygène`, 'SpO₂': `saturation pulsée en oxygène (saturomètre)`,
    'HCO₃⁻': `bicarbonates`, 'CO': `monoxyde de carbone`, 'Hb': `hémoglobine`,
    'VEMS': `volume expiratoire maximal en 1 seconde`, 'DEP': `débit expiratoire de pointe`, 'FR': `fréquence respiratoire`,
    'BPCO': `broncho-pneumopathie chronique obstructive`, 'SAHOS': `syndrome d’apnées-hypopnées obstructives du sommeil`,
    'IAH': `index d’apnées-hypopnées`, 'PPC': `pression positive continue`, 'mMRC': `échelle de dyspnée (modified Medical Research Council)`,
    'ACT': `Asthma Control Test (test de contrôle de l’asthme)`, 'VNI': `ventilation non invasive`,
    'DTPCoq': `diphtérie, tétanos, poliomyélite, coqueluche`, 'VRS': `virus respiratoire syncytial`,
    'RCP': `résumé des caractéristiques du produit`, 'ADME': `absorption, distribution, métabolisme, élimination`,
    'RAA': `rhumatisme articulaire aigu`,
    'IDE': `infirmier diplômé d’État`, 'ESI': `étudiant en soins infirmiers`, 'AS': `aide-soignant`, 'AP': `auxiliaire de puériculture`,
    'AES': `accompagnant éducatif et social`, 'IPA': `infirmier en pratique avancée`, 'CSP': `Code de la santé publique`, 'CP': `Code pénal`,
    'VIH': `virus de l’immunodéficience humaine`, 'IFSI': `institut de formation en soins infirmiers`,
    'CRCI': `commission régionale de conciliation et d’indemnisation`, 'ONIAM': `Office national d’indemnisation des accidents médicaux`,
    'CADA': `Commission d’accès aux documents administratifs`, 'CNIL': `Commission nationale de l’informatique et des libertés`,
    'EHPAD': `établissement d’hébergement pour personnes âgées dépendantes`,
    'EBM': `evidence-based medicine (médecine fondée sur les preuves)`, 'ENT': `environnement numérique de travail`,
    'MeSH': `Medical Subject Headings (thésaurus de PubMed)`, 'SUDOC': `Système universitaire de documentation`,
    'BU': `bibliothèque universitaire`, 'BDSP': `Banque de données en santé publique`,
    'ST': `segment ST de l’ECG (sus- ou sous-décalage)`, 'AVC': `accident vasculaire cérébral`, 'VAS': `voies aériennes supérieures`,
    'AG': `anesthésie générale`, 'PD': `pharmacodynamie`, 'PK': `pharmacocinétique`, 'NaCl': `chlorure de sodium`,
    'FiO₂': `fraction inspirée en oxygène`, 'DASRI': `déchets d’activités de soins à risques infectieux`, 'OPCT': `objets piquants, coupants, tranchants`,
    'SHA': `solution hydro-alcoolique`, 'EPI': `équipement de protection individuelle`, 'DCI': `dénomination commune internationale`,
    'RPPS': `répertoire partagé des professionnels de santé`, 'SAED': `Situation, Antécédents, Évaluation, Demande`,
    'TCA': `temps de céphaline activée`, 'LP': `libération prolongée`, 'SRAA': `système rénine-angiotensine-aldostérone`,
    'EVS': `échelle verbale simple`, 'DOLOPLUS': `échelle d’hétéro-évaluation de la douleur de la personne âgée`,
    'ECPA': `échelle comportementale de la douleur chez la personne âgée`, 'ALGOPLUS': `échelle d’hétéro-évaluation de la douleur aiguë de la personne âgée`,
    'VHB': `virus de l’hépatite B`, 'VHC': `virus de l’hépatite C`, 'UI': `unités internationales`, 'EIC': `espace intercostal`,
    'LDL': `lipoprotéines de basse densité (« mauvais cholestérol »)`, 'KCl': `chlorure de potassium`,
    'CCNE': `Comité consultatif national d’éthique`, 'CFS': `Clinical Frailty Scale (échelle de fragilité de Rockwood)`,
    'HAS': `Haute Autorité de santé`, 'DAR': `Données, Actions, Résultats`,
    'PubMed': `base bibliographique biomédicale`, 'CAIRN': `portail de revues en sciences humaines et sociales`,
    'DOI': `identifiant numérique unique d’un document (Digital Object Identifier)`, 'IA': `intelligence artificielle`
  };

  return { v: 1, sets, glossary, get: id => sets.find(s => s.id === id) };
})();
